  if (!company?.stampUrl) return null;
  return (
    <div className="absolute top-8 left-8 w-32 h-32 opacity-70 print:opacity-40">
      <img src={company.stampUrl} alt="Stamp" className="w-full h-full object-contain" />
    </div>
  );
}

"use client";
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { API_BASE_URL } from '@/lib/api';
import { User, Building, Phone, Mail, FileText, MapPin, MoreVertical, Edit, Trash2, Plus, X } from 'lucide-react';

export default function ContactsPage() {
  const [activeTab, setActiveTab] = useState<'suppliers' | 'clients'>('suppliers');
  const [data, setData] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<any>(null);

  const [formData, setFormData] = useState({
    name: '',
    commercialName: '',
    contactPerson: '',
    phone: '',
    email: '',
    taxNumber: '',
    crNumber: '',
    address: '',
    activityType: '',
    notes: ''
  });

  useEffect(() => {
    fetchData();
  }, [activeTab]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get(`${API_BASE_URL}/v1/contacts/${activeTab}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setData(res.data);
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const openNewModal = () => {
    setEditingItem(null);
    setFormData({
      name: '', commercialName: '', contactPerson: '', phone: '', email: '', 
      taxNumber: '', crNumber: '', address: '', activityType: '', notes: ''
    });
    setIsModalOpen(true);
  };

  const openEditModal = (item: any) => {
    setEditingItem(item);
    setFormData({
      name: item.name || '',
      commercialName: item.commercialName || '',
      contactPerson: item.contactPerson || '',
      phone: item.phone || '',
      email: item.email || '',
      taxNumber: item.taxNumber || '',
      crNumber: item.crNumber || '',
      address: item.address || '',
      activityType: item.activityType || '',
      notes: item.notes || ''
    });
    setIsModalOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm("هل أنت متأكد من حذف هذا السجل بشكل نهائي؟")) return;
    try {
      const token = localStorage.getItem("token");
      await axios.delete(`${API_BASE_URL}/v1/contacts/${activeTab}/${id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      fetchData();
    } catch (err) {
      alert("حدث خطأ أثناء الحذف، ربما السجل مرتبط بعمليات مالية!");
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const token = localStorage.getItem("token");
      if (editingItem) {
        await axios.put(`${API_BASE_URL}/v1/contacts/${activeTab}/${editingItem.id}`, formData, {
          headers: { Authorization: `Bearer ${token}` }
        });
      } else {
        await axios.post(`${API_BASE_URL}/v1/contacts/${activeTab}`, formData, {
          headers: { Authorization: `Bearer ${token}` }
        });
      }
      setIsModalOpen(false);
      fetchData();
    } catch (err: any) {
      alert(`حدث خطأ أثناء الحفظ:\n${err.response?.data?.message || err.message}`);
    }
  };

  return (
    <div className="p-6 md:p-10 space-y-8 animate-in fade-in zoom-in duration-500">
      
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-slate-900/50 p-6 rounded-3xl border border-slate-800 backdrop-blur-xl">
        <div>
          <h1 className="text-3xl font-bold text-white flex items-center gap-3">
            <Building className="text-indigo-500" size={32} />
            إدارة جهات الاتصال (CRM)
          </h1>
          <p className="text-slate-400 mt-2 text-sm">
            أرشيف متكامل لإدارة بيانات الموردين والعملاء والسجلات الضريبية بحرية كاملة
          </p>
        </div>
        <button 
          onClick={openNewModal}
          className="bg-indigo-600 hover:bg-indigo-500 text-white px-6 py-3 rounded-2xl shadow-lg transition-all flex items-center gap-2 font-medium"
        >
          <Plus size={20} />
          إضافة {activeTab === 'suppliers' ? 'مورد جديد' : 'عميل جديد'}
        </button>
      </div>

      {/* Tabs */}
      <div className="flex p-1 bg-slate-900/50 backdrop-blur-sm rounded-2xl w-full max-w-md mx-auto border border-slate-800">
        <button 
          onClick={() => setActiveTab('suppliers')}
          className={`flex-1 py-3 text-sm font-bold rounded-xl transition-all flex justify-center items-center gap-2 ${activeTab === 'suppliers' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}
        >
           قائمة الموردين
        </button>
        <button 
          onClick={() => setActiveTab('clients')}
          className={`flex-1 py-3 text-sm font-bold rounded-xl transition-all flex justify-center items-center gap-2 ${activeTab === 'clients' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}
        >
           قائمة العملاء
        </button>
      </div>

      {/* Cards Grid */}
      {isLoading ? (
        <div className="flex justify-center py-20"><div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div></div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {data.map((item) => (
            <div key={item.id} className="group bg-slate-900/40 backdrop-blur-md rounded-3xl border border-slate-800/80 hover:border-indigo-500/50 p-6 flex flex-col gap-4 shadow-xl transition-all hover:-translate-y-1 relative overflow-hidden">
              <div className={`absolute top-0 right-0 w-full h-1 ${activeTab === 'suppliers' ? 'bg-gradient-to-r from-transparent via-indigo-500 to-transparent' : 'bg-gradient-to-r from-transparent via-blue-500 to-transparent'} opacity-0 group-hover:opacity-100 transition-opacity`}></div>
              
              <div className="flex justify-between items-start">
                <div className="flex-1">
                  <h3 className="text-xl font-bold text-white mb-1 flex items-center gap-2">
                    {item.name} 
                  </h3>
                  <p className="text-sm text-slate-400 font-medium">
                    {item.commercialName || "لم يسجل الاسم التجاري"}
                  </p>
                </div>
                <div className="flex items-center gap-2">
                  <button onClick={() => openEditModal(item)} className="p-2 bg-slate-800 hover:bg-indigo-600 text-slate-300 hover:text-white rounded-xl transition-colors">
                    <Edit size={16} />
                  </button>
                  <button onClick={() => handleDelete(item.id)} className="p-2 bg-slate-800 hover:bg-rose-600 text-slate-300 hover:text-white rounded-xl transition-colors">
                    <Trash2 size={16} />
                  </button>
                </div>
              </div>

              <div className="h-px w-full bg-gradient-to-r from-transparent via-slate-700 to-transparent my-1"></div>

              <div className="space-y-3 text-sm">
                 <div className="flex items-start gap-3">
                   <div className="mt-0.5 p-1.5 rounded-lg bg-slate-800/50 text-indigo-400"><FileText size={14} /></div>
                   <div className="flex-1">
                     <p className="text-slate-500 text-xs">الرقم الضريبي والسجل</p>
                     <p className="text-slate-300">{item.taxNumber ? `ضريبي: ${item.taxNumber}` : 'لا يوجد ضرائب'} {item.crNumber ? `| س.ت: ${item.crNumber}` : ''}</p>
                   </div>
                 </div>
                 
                 <div className="flex items-start gap-3">
                   <div className="mt-0.5 p-1.5 rounded-lg bg-slate-800/50 text-indigo-400"><MapPin size={14} /></div>
                   <div className="flex-1">
                     <p className="text-slate-500 text-xs">العنوان</p>
                     <p className="text-slate-300">{item.address || 'غير محدد'}</p>
                   </div>
                 </div>

                 <div className="flex items-center gap-3">
                   <div className="p-1.5 rounded-lg bg-slate-800/50 text-indigo-400"><Phone size={14} /></div>
                   <p className="text-slate-300">{item.phone || 'بدون هاتف'}</p>
                 </div>
              </div>

              {item.notes && (
                <div className="mt-2 p-3 rounded-xl bg-slate-800/30 text-slate-400 text-xs italic border border-slate-700/30">
                  "{item.notes}"
                </div>
              )}
            </div>
          ))}

          {data.length === 0 && (
            <div className="col-span-full py-20 text-center flex flex-col items-center justify-center border-2 border-dashed border-slate-800 rounded-3xl">
              <User size={48} className="text-slate-600 mb-4" />
              <h3 className="text-xl font-bold text-slate-300 mb-2">لا يوجد سجلات</h3>
              <p className="text-slate-500">اضغط على زر الإضافة لإنشاء القيد الأول في قاعدة البيانات.</p>
            </div>
          )}
        </div>
      )}

      {/* Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-slate-900 border border-slate-700 rounded-3xl w-full max-w-2xl overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
            <div className="p-6 border-b border-slate-800 flex justify-between items-center bg-slate-800/30">
              <h2 className="text-xl font-bold text-white flex items-center gap-2">
                {editingItem ? <Edit size={20} className="text-indigo-400" /> : <Plus size={20} className="text-indigo-400" />}
                {editingItem ? 'تعديل السجل' : 'إضافة سجل جديد'}
              </h2>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-white p-2 rounded-xl hover:bg-slate-800 transition-colors">
                <X size={20} />
              </button>
            </div>
            
            <form onSubmit={handleSubmit} className="p-6 overflow-y-auto custom-scrollbar">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <div className="space-y-2">
                  <label className="text-sm font-semibold text-slate-300">* الاسم المختصر (اساسي)</label>
                  <input required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500" placeholder="مثال: الراجحي" />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-semibold text-slate-300">الاسم التجاري الكامل</label>
                  <input value={formData.commercialName} onChange={e => setFormData({...formData, commercialName: e.target.value})} className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-indigo-500" placeholder="مثال: شركة الراجحي للحديد المحدودة" />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-semibold text-slate-300">الرقم الضريبي VAT</label>
                  <input value={formData.taxNumber} onChange={e => setFormData({...formData, taxNumber: e.target.value})} className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-indigo-500" placeholder="3000..." />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-semibold text-slate-300">رقم السجل التجاري CR</label>
                  <input value={formData.crNumber} onChange={e => setFormData({...formData, crNumber: e.target.value})} className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-indigo-500" placeholder="1010..." />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-semibold text-slate-300">رقم الهاتف التواصل</label>
                  <input value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-indigo-500" placeholder="05xxxxxxxx" />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-semibold text-slate-300">البريد الإلكتروني</label>
                  <input type="email" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-indigo-500" placeholder="info@example.com" />
                </div>
                <div className="space-y-2 md:col-span-2">
                  <label className="text-sm font-semibold text-slate-300">العنوان أو المقر</label>
                  <input value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-indigo-500" placeholder="الرياض، حي السلي، شارع اسطنبول" />
                </div>
                <div className="space-y-2 md:col-span-2">
                  <label className="text-sm font-semibold text-slate-300">نوع النشاط (اختياري)</label>
                  <input value={formData.activityType} onChange={e => setFormData({...formData, activityType: e.target.value})} className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-indigo-500" placeholder="مثال: توريد مواد بناء، مقاولات عامة..." />
                </div>
                <div className="space-y-2 md:col-span-2">
                  <label className="text-sm font-semibold text-slate-300">ملاحظات داخلية / أرقام تواصل أخرى</label>
                  <textarea rows={3} value={formData.notes} onChange={e => setFormData({...formData, notes: e.target.value})} className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-indigo-500 resize-none" placeholder="اكتب أي معلومات إضافية عن هذه الجهة..." />
                </div>
              </div>
              <div className="mt-8 pt-6 border-t border-slate-800 flex gap-4">
                <button type="submit" className="flex-1 bg-indigo-600 hover:bg-indigo-500 text-white font-bold py-3.5 rounded-xl transition-colors">
                  {editingItem ? 'حفظ التعديلات' : 'إضافة إلى الأرشيف'}
                </button>
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 bg-slate-800 hover:bg-slate-700 text-white font-bold py-3.5 rounded-xl transition-colors">
                  إلغاء
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { API_BASE_URL } from "@/lib/api";
import { useRouter, useParams } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import {
  FileSignature, Save, ArrowRight, Loader2, Plus, Trash2, ShieldQuestion, Wallet
} from "lucide-react";
import axios from "axios";

export default function CreateChangeOrderPage() {
  const router = useRouter();
  const params = useParams();
  const contractId = params.id as string;

  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [contract, setContract] = useState<any>(null);

  const [formData, setFormData] = useState({
    title: "",
    type: "ADDITION", // ADDITION | DEDUCTION
    status: "APPROVED"
  });

  const [items, setItems] = useState<any[]>([
    { description: "", quantityChange: 1, unitPrice: 0 }
  ]);

  useEffect(() => {
    if (contractId) fetchContract();
  }, [contractId]);

  const fetchContract = async () => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get(`${API_BASE_URL}/v1/contracts/${contractId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setContract(res.data);
    } catch (err) {
      alert("لم يتم العثور على العقد.");
      router.push("/dashboard/contracts");
    } finally {
      setIsLoading(false);
    }
  };

  const calculateTotal = () => {
    return items.reduce((acc, item) => {
      const qty = Number(item.quantityChange) || 0;
      const price = Number(item.unitPrice) || 0;
      return acc + (qty * price);
    }, 0);
  };

  const addItem = () => {
    setItems([...items, { description: "", quantityChange: 1, unitPrice: 0 }]);
  };

  const removeItem = (index: number) => {
    setItems(items.filter((_, i) => i !== index));
  };

  const updateItem = (index: number, field: string, value: any) => {
    const newItems = [...items];
    newItems[index][field] = value;
    setItems(newItems);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validate items
    if (items.length === 0 || items.some(i => !i.description)) {
      alert("يرجى إدخال بند واحد على الأقل وتعبئة وصفه.");
      return;
    }

    setIsSaving(true);
    const amount = calculateTotal();

    try {
      const token = localStorage.getItem("token");
      await axios.post(
        `${API_BASE_URL}/v1/contracts/${contractId}/change-orders`,
        {
          ...formData,
          amount,
          items: items.map(i => ({
            ...i,
            quantityChange: Number(i.quantityChange),
            unitPrice: Number(i.unitPrice)
          }))
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      router.push(`/dashboard/contracts/edit/${contractId}`);
    } catch (err: any) {
      alert(`خطأ أثناء إنشاء الملحق: ${err.response?.data?.message || err.message}`);
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <Loader2 className="animate-spin text-emerald-500" size={48} />
      </div>
    );
  }

  const isMain = contract?.type === "MAIN_CONTRACT";
  const partyName = isMain
    ? (contract?.project?.client?.name || "الجهة المالكة")
    : (contract?.subcontractor?.name || "مقاول باطن");
  const totalAmount = calculateTotal();

  return (
    <div className="max-w-4xl mx-auto space-y-6 w-full animate-in fade-in zoom-in-95 duration-500 pb-12">
      {/* Header */}
      <div className="flex items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <button
            onClick={() => router.push(`/dashboard/contracts/edit/${contractId}`)}
            className="p-2.5 rounded-xl bg-white/5 hover:bg-white/10 text-slate-300 transition-colors"
          >
            <ArrowRight size={20} />
          </button>
          <div>
            <h1 className="text-2xl font-bold text-white flex items-center gap-3">
              <FileSignature className="text-emerald-400" size={24} />
              تصميم ملحق عقد (أمر تغييري)
            </h1>
            <p className="text-slate-400 text-sm mt-1">
              إضافة تغيرات مالية أو كميات على العقد رقم: <span className="font-mono text-white">[{contract?.referenceNumber}]</span>
            </p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">

        {/* Core Form */}
        <motion.div
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          className="md:col-span-2 glass-dark border border-white/5 rounded-3xl p-6"
        >
          <form id="co-form" onSubmit={handleSubmit} className="space-y-6">

            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-300 flex items-center gap-2">
                عنوان الملحق / الغرض المستحدث
              </label>
              <input
                type="text"
                required
                value={formData.title}
                onChange={e => setFormData({ ...formData, title: e.target.value })}
                className="w-full bg-slate-900/50 border border-slate-800 rounded-xl py-3 px-4 text-white placeholder-slate-500 focus:outline-none focus:border-emerald-500/50 transition-all font-medium text-lg"
                placeholder="مثال: زيادة كميات خرسانة السقف دور 1..."
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div
                onClick={() => setFormData({ ...formData, type: 'ADDITION' })}
                className={`p-4 rounded-2xl border cursor-pointer flex flex-col items-center justify-center gap-2 transition-all group ${
                  formData.type === 'ADDITION' 
                    ? 'bg-emerald-500/10 border-emerald-500/50 shadow-[0_0_20px_rgba(16,185,129,0.15)] shadow-inner' 
                    : 'bg-slate-900/50 border-slate-800 hover:border-slate-700'
                }`}
              >
                <div className={`p-2 rounded-full ${formData.type === 'ADDITION' ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-500/40' : 'bg-slate-800 text-slate-400 group-hover:text-white'}`}>
                  <Plus size={20} />
                </div>
                <span className={`font-bold ${formData.type === 'ADDITION' ? 'text-emerald-400' : 'text-slate-400 group-hover:text-slate-300'}`}>ملحق إضافة / زيادة</span>
              </div>

              <div
                onClick={() => setFormData({ ...formData, type: 'DEDUCTION' })}
                className={`p-4 rounded-2xl border cursor-pointer flex flex-col items-center justify-center gap-2 transition-all group ${
                  formData.type === 'DEDUCTION' 
                    ? 'bg-rose-500/10 border-rose-500/50 shadow-[0_0_20px_rgba(244,63,94,0.15)] shadow-inner' 
                    : 'bg-slate-900/50 border-slate-800 hover:border-slate-700'
                }`}
              >
                <div className={`p-2 rounded-full ${formData.type === 'DEDUCTION' ? 'bg-rose-500 text-white shadow-lg shadow-rose-500/40' : 'bg-slate-800 text-slate-400 group-hover:text-white'}`}>
                  <ShieldQuestion size={20} />
                </div>
                <span className={`font-bold ${formData.type === 'DEDUCTION' ? 'text-rose-400' : 'text-slate-400 group-hover:text-slate-300'}`}>ملحق تنزيل / استبعاد</span>
              </div>
            </div>

            {/* Items List */}
            <div className="pt-6 border-t border-white/5 space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-lg font-bold text-white flex items-center gap-2">
                  <Wallet size={18} className="text-emerald-400" />
                  بنود الملحق التفصيلية
                </h3>
                <button
                  type="button"
                  onClick={addItem}
                  className="px-3 py-1.5 rounded-lg text-xs font-bold bg-emerald-500/10 text-emerald-400 hover:bg-emerald-500/20 transition-colors flex items-center gap-1.5 border border-emerald-500/20"
                >
                  <Plus size={14} /> إضافة بند
                </button>
              </div>

              <div className="space-y-3">
                <AnimatePresence>
                  {items.map((item, index) => (
                    <motion.div
                      initial={{ opacity: 0, height: 0 }}
                      animate={{ opacity: 1, height: 'auto' }}
                      exit={{ opacity: 0, height: 0 }}
                      key={index}
                      className="bg-slate-900/40 border border-slate-800 rounded-xl p-4 flex flex-col sm:flex-row gap-4 relative group"
                    >
                      <div className="flex-1 space-y-2">
                        <label className="text-xs text-slate-400">وصف البند التغييري</label>
                        <input
                          type="text"
                          required
                          value={item.description}
                          onChange={(e) => updateItem(index, 'description', e.target.value)}
                          placeholder="مثال: توريد مواد عزل مرنة..."
                          className="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 text-white text-sm focus:outline-none focus:border-emerald-500"
                        />
                      </div>
                      <div className="w-full sm:w-24 space-y-2">
                        <label className="text-xs text-slate-400">الكمية</label>
                        <input
                          type="number"
                          required
                          step="any"
                          min="0"
                          value={item.quantityChange}
                          onChange={(e) => updateItem(index, 'quantityChange', e.target.value)}
                          className="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 text-white text-sm text-center focus:outline-none focus:border-emerald-500"
                        />
                      </div>
                      <div className="w-full sm:w-32 space-y-2">
                        <label className="text-xs text-slate-400">سعر الوحدة (SAR)</label>
                        <input
                          type="number"
                          required
                          step="any"
                          min="0"
                          value={item.unitPrice}
                          onChange={(e) => updateItem(index, 'unitPrice', e.target.value)}
                          className="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 text-white text-sm text-center focus:outline-none focus:border-emerald-500"
                        />
                      </div>

                      {items.length > 1 && (
                        <button
                          type="button"
                          onClick={() => removeItem(index)}
                          className="absolute -left-2 -top-2 w-7 h-7 rounded-full bg-rose-500 flex items-center justify-center text-white opacity-0 sm:group-hover:opacity-100 transition-opacity shadow-lg"
                        >
                          <Trash2 size={12} />
                        </button>
                      )}

                      {/* Subtotal Label */}
                      <div className="absolute left-4 bottom-4 sm:top-1/2 sm:-translate-y-1/2 sm:bottom-auto font-mono text-xs font-bold text-emerald-400 opacity-60">
                        = {(Number(item.quantityChange) * Number(item.unitPrice) || 0).toLocaleString()} S
                      </div>
                    </motion.div>
                  ))}
                </AnimatePresence>
              </div>
            </div>

          </form>
        </motion.div>

        {/* Sidebar Summary */}
        <motion.div
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          className="space-y-6"
        >
          <div className="glass-dark border border-white/5 rounded-3xl p-6 relative overflow-hidden">
            <div className={`absolute -right-10 -top-10 w-32 h-32 rounded-full blur-[40px] opacity-20 pointer-events-none ${formData.type === 'ADDITION' ? 'bg-emerald-500' : 'bg-rose-500'}`} />

            <h3 className="text-lg font-bold text-white mb-6">ملخص الملحق المالي</h3>

            <div className="space-y-4">
              <div className="flex items-center justify-between text-sm">
                <span className="text-slate-400">الطرف المعني</span>
                <span className="font-bold text-white max-w-[140px] truncate" title={partyName}>{partyName}</span>
              </div>
              <div className="flex items-center justify-between text-sm">
                <span className="text-slate-400">نوع الملحق</span>
                <span className={`font-bold ${formData.type === 'ADDITION' ? 'text-emerald-400' : 'text-rose-400'}`}>
                  {formData.type === 'ADDITION' ? 'زيادة بالمبلغ' : 'استقطاع / تنزيل'}
                </span>
              </div>

              <div className="pt-4 border-t border-white/10">
                <div className="flex items-center justify-between text-sm mb-1">
                  <span className="text-slate-400">إجمالي الملحق (SAR)</span>
                  <span className={`font-mono text-xl font-black ${formData.type === 'ADDITION' ? 'text-emerald-400' : 'text-rose-400'}`}>
                    {formData.type === 'DEDUCTION' && totalAmount > 0 ? '-' : ''}{totalAmount.toLocaleString('en-US')}
                  </span>
                </div>
              </div>
            </div>

            <button
              type="submit"
              form="co-form"
              disabled={isSaving || totalAmount === 0}
              className={`w-full mt-8 py-3.5 rounded-2xl font-bold flex items-center justify-center gap-2 transition-all disabled:opacity-50 text-white shadow-xl ${
                formData.type === 'ADDITION' 
                  ? "bg-gradient-to-r from-emerald-600 to-teal-500 hover:from-emerald-500 hover:to-teal-400 shadow-emerald-500/25"
                  : "bg-gradient-to-r from-rose-600 to-pink-600 hover:from-rose-500 hover:to-pink-500 shadow-rose-500/25"
              }`}
            >
              {isSaving ? <Loader2 size={18} className="animate-spin" /> : <Save size={18} />}
              اعتماد وإنشاء الملحق
            </button>
            <p className="text-center text-xs text-slate-500 mt-4 leading-relaxed">
              بموجب الاعتماد، سيتم {formData.type === 'ADDITION' ? 'زيادة' : 'خصم'} هذه القيمة لإجمالي العمليات.
            </p>
          </div>
        </motion.div>

      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { motion } from "framer-motion";
import { FileSignature, Save, ArrowRight, Loader2, Wallet } from "lucide-react";
import axios from "axios";
import { API_BASE_URL } from "@/lib/api";

export default function CreateContractPage() {
  const router = useRouter();
  const [isLoading, setIsLoading] = useState(false);
  const [projects, setProjects] = useState<any[]>([]);
  const [suppliers, setSuppliers] = useState<any[]>([]);
  const [projectBoq, setProjectBoq] = useState<any[]>([]);
  const [selectedItems, setSelectedItems] = useState<any[]>([]);
  const [showBoqSelector, setShowBoqSelector] = useState(false);
  
  const [formData, setFormData] = useState({
    projectId: "",
    subcontractorId: "",
    type: "SUBCONTRACT",
    referenceNumber: "",
    totalValue: 0,
    retentionPercent: 5,
    advancePayment: 10
  });

  const fetchProjects = async () => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get(`${API_BASE_URL}/v1/projects`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProjects(res.data);
      if (res.data.length > 0) {
        setFormData(prev => ({ ...prev, projectId: res.data[0].id }));
      }
    } catch (err) {}
  };

  const fetchSuppliers = async () => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get(`${API_BASE_URL}/v1/contacts/suppliers`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setSuppliers(res.data);
      if (res.data.length > 0) {
        setFormData(prev => ({ ...prev, subcontractorId: res.data[0].id }));
      }
    } catch (err) {}
  };

  useEffect(() => {
    fetchProjects();
    fetchSuppliers();
  }, []);

  useEffect(() => {
    if (formData.projectId) {
      fetchProjectBoq(formData.projectId);
      setSelectedItems([]); // reset items if project changes
    }
  }, [formData.projectId]);

  const fetchProjectBoq = async (pid: string) => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get(`${API_BASE_URL}/v1/projects/${pid}/boq`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProjectBoq(res.data);
    } catch (err) {}
  };

  const handleAddItem = (item: any) => {
    if (selectedItems.find(it => it.boqItemId === item.id)) return;
    
    // Calculate committed quantity from OTHER contracts of the same type
    const committedToOthers = (item.contractItems || [])
      .filter((ci: any) => ci.contract?.type === formData.type)
      .reduce((acc: any, ci: any) => acc + Number(ci.assignedQty), 0);
    const remaining = Math.max(0, item.quantity - committedToOthers);

    const defaultPrice = formData.type === "SUBCONTRACT" ? (item.subcontractorPrice || 0) : item.unitPrice;

    setSelectedItems([...selectedItems, {
      boqItemId: item.id,
      description: item.description,
      unit: item.unit,
      assignedQty: remaining, // default to what is actually available!
      unitPrice: defaultPrice, 
    }]);
    setShowBoqSelector(false);
  };

  const removeItem = (id: string) => {
    setSelectedItems(selectedItems.filter(it => it.boqItemId !== id));
  };

  const updateItemValue = (id: string, field: string, value: string) => {
    setSelectedItems(prev => prev.map(it => 
      it.boqItemId === id ? { ...it, [field]: value } : it
    ));
  };

  // Auto-calculate Total Value
  const calculatedTotal = selectedItems.reduce((acc, it) => acc + (Number(it.assignedQty) * Number(it.unitPrice)), 0);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const token = localStorage.getItem("token");
      await axios.post(
        `${API_BASE_URL}/v1/contracts`,
        { ...formData, items: selectedItems, totalValue: calculatedTotal },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      router.push("/dashboard/contracts");
    } catch (err: any) {
      const errData = err.response?.data || err.message;
      alert(`حدث خطأ أثناء حفظ العقد:\n${typeof errData === 'object' ? JSON.stringify(errData, null, 2) : errData}`);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-6 w-full animate-in fade-in zoom-in-95 duration-500 pb-12">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <button onClick={() => router.back()} className="p-2.5 rounded-xl bg-white/5 hover:bg-white/10 text-slate-300 transition-colors">
            <ArrowRight size={20} />
          </button>
          <div>
            <h1 className="text-2xl font-bold text-white flex items-center gap-3">
              <FileSignature className="text-orange-500" size={24} />
              تسجيل عقد جديد
            </h1>
            <p className="text-slate-400 text-sm mt-1">تأسيس عقد مقاول باطن أو مورد وربطه بالمشروع.</p>
          </div>
        </div>
      </div>

      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="glass-dark border border-white/5 rounded-3xl p-6 sm:p-8">
        <form onSubmit={handleSubmit} className="space-y-8">
          
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-300">المشروع المرتبط</label>
              <select
                required
                value={formData.projectId}
                onChange={e => setFormData({...formData, projectId: e.target.value})}
                className="w-full bg-slate-900/50 border border-slate-800 rounded-xl py-3 px-4 text-white focus:outline-none focus:ring-2 focus:ring-orange-500/50 transition-all appearance-none cursor-pointer"
              >
                {projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
              </select>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-300">رقم العقد المرجعي (REF)</label>
              <input type="text" required value={formData.referenceNumber} onChange={e => setFormData({...formData, referenceNumber: e.target.value})} className="w-full bg-slate-900/50 border border-slate-800 rounded-xl py-3 px-4 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-orange-500/50 transition-all" placeholder="CT-2026-X01" dir="ltr" />
            </div>

            <div className="space-y-2 md:col-span-2">
              <label className="text-sm font-medium text-slate-300">نوع العقد (التوجيه المحاسبي)</label>
               <select
                required
                value={formData.type}
                onChange={e => setFormData({...formData, type: e.target.value})}
                className="w-full bg-slate-900/50 border border-slate-800 rounded-xl py-3 px-4 text-white focus:outline-none focus:ring-2 focus:ring-orange-500/50 transition-all appearance-none cursor-pointer"
              >
                <option value="SUBCONTRACT">عقد مقاول باطن (مشتريات/مصروف)</option>
                <option value="MAIN_CONTRACT">عقد رئيسي مع المالك (مبيعات/إيراد)</option>
              </select>
            </div>

            {formData.type === "SUBCONTRACT" && (
              <div className="space-y-2 md:col-span-2">
                <label className="text-sm font-medium text-slate-300">اختر مقاول الباطن / المورد</label>
                <select
                  required
                  value={formData.subcontractorId}
                  onChange={e => setFormData({...formData, subcontractorId: e.target.value})}
                  className="w-full bg-slate-900/50 border border-slate-800 rounded-xl py-3 px-4 text-white focus:outline-none focus:ring-2 focus:ring-orange-500/50 transition-all appearance-none cursor-pointer"
                >
                  <option value="" disabled>اختر المقاول من القائمة الإدارية</option>
                  {suppliers.map(s => (
                    <option key={s.id} value={s.id}>
                      {s.name} {s.daftraSupplierId ? '(مربوط)' : '(غير مربوط)'}
                    </option>
                  ))}
                </select>
                <p className="text-xs text-slate-500 mt-1">يجب أن يكون المقاول مربوطاً بدفترة لتتمكن من ترحيل مستخلصاته لاحقاً.</p>
              </div>
            )}

            <div className="space-y-4 border border-blue-500/30 p-5 rounded-3xl bg-blue-500/5 col-span-1 md:col-span-2">
              <div className="flex items-center justify-between mb-2">
                <label className="text-sm font-bold text-blue-400 flex items-center gap-2">
                   <div className="w-2 h-2 rounded-full bg-blue-500 animate-pulse" />
                   بنود وجدول كميات العقد (Scope of Work)
                </label>
                <button 
                  type="button"
                  onClick={() => setShowBoqSelector(true)}
                  className="px-4 py-1.5 bg-blue-600 hover:bg-blue-500 text-white text-xs font-bold rounded-xl transition-all shadow-lg flex items-center gap-2"
                >
                  <span className="text-lg">+</span> إضافة بند من المشروع
                </button>
              </div>

              {selectedItems.length === 0 ? (
                <div className="py-10 text-center text-slate-500 border-2 border-dashed border-white/5 rounded-2xl">
                  لم يتم إضافة بنود للعقد بعد. اضغط على زر الإضافة لاختيار مهام من جدول كميات المشروع.
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full text-right text-xs text-slate-300">
                    <thead className="border-b border-white/10 uppercase font-bold text-[10px] text-slate-500">
                      <tr>
                        <th className="pb-3 pr-2">وصف البند</th>
                        <th className="pb-3 text-center">الكمية المسندة</th>
                        <th className="pb-3 text-center">سعر المتر (مقاول)</th>
                        <th className="pb-3 text-left">إجمالي البند</th>
                        <th className="pb-3 text-center w-10">#</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-white/5">
                      {selectedItems.map((it) => (
                        <tr key={it.boqItemId} className="group transition-colors hover:bg-white/5">
                          <td className="py-4 pr-2">
                            <p className="font-bold text-white mb-0.5">{it.description}</p>
                            <p className="text-[10px] text-slate-500 font-mono italic">Unit: {it.unit}</p>
                          </td>
                          <td className="py-4 text-center">
                            <input 
                              type="number" 
                              value={it.assignedQty} 
                              onChange={e => updateItemValue(it.boqItemId, 'assignedQty', e.target.value)}
                              className="w-20 bg-slate-900 border border-slate-700 rounded-lg text-center py-1.5 font-mono text-emerald-400 focus:outline-none focus:border-emerald-500/50 transition-all"
                            />
                          </td>
                          <td className="py-4 text-center">
                            <input 
                              type="number" 
                              value={it.unitPrice} 
                              onChange={e => updateItemValue(it.boqItemId, 'unitPrice', e.target.value)}
                              className="w-24 bg-slate-900 border border-slate-700 rounded-lg text-center py-1.5 font-mono text-blue-400 focus:outline-none focus:border-blue-500/50 transition-all"
                            />
                          </td>
                          <td className="py-4 text-left font-mono font-bold text-white text-[13px]">
                            {(Number(it.assignedQty) * Number(it.unitPrice)).toLocaleString(undefined, {minimumFractionDigits: 2})}
                          </td>
                          <td className="py-4 text-center">
                            <button type="button" onClick={() => removeItem(it.boqItemId)} className="p-1.5 text-slate-600 hover:text-rose-500 hover:bg-rose-500/10 rounded-lg transition-all">
                              ✕
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                    <tfoot>
                      <tr className="border-t border-blue-500/20">
                        <td colSpan={3} className="py-5 text-left font-bold text-slate-400">إجمالي قيمة العقد (تلقائي):</td>
                        <td className="py-5 text-left font-mono font-black text-blue-400 text-xl">
                          <span className="text-xs text-slate-500 mr-1">SAR</span>
                          {calculatedTotal.toLocaleString(undefined, {minimumFractionDigits: 2})}
                        </td>
                        <td></td>
                      </tr>
                    </tfoot>
                  </table>
                </div>
              )}
            </div>

            {/* BOQ Selector Modal */}
            {showBoqSelector && (
              <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md">
                <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="bg-slate-900 border border-white/10 w-full max-w-3xl rounded-[2.5rem] p-8 shadow-2xl relative overflow-hidden">
                  <div className="absolute top-0 right-0 w-64 h-64 bg-blue-500/5 rounded-full blur-[80px] -z-10" />
                  
                  <div className="flex justify-between items-center mb-8">
                    <div>
                        <h3 className="text-2xl font-black text-white">جدول كميات المشروع</h3>
                        <p className="text-sm text-slate-400 mt-1">اختر البنود التي تود إسنادها لهذا المقاول</p>
                    </div>
                    <button onClick={() => setShowBoqSelector(false)} className="w-10 h-10 flex items-center justify-center rounded-2xl bg-white/5 text-slate-400 hover:text-white transition-colors">✕</button>
                  </div>
                  
                  <div className="max-h-[450px] overflow-y-auto space-y-3 pr-4 custom-scrollbar">
                    {projectBoq.length === 0 ? (
                      <div className="text-center py-20 text-slate-500 flex flex-col items-center gap-4">
                         <div className="p-4 rounded-full bg-white/5"><Loader2 className="animate-spin text-slate-400" /></div>
                         <p>لا توجد بنود متاحة حالياً في المشروع.</p>
                      </div>
                    ) : (
                      projectBoq.map(it => {
                        const committed = (it.contractItems || [])
                          .filter((ci: any) => ci.contract?.type === formData.type)
                          .reduce((acc: number, ci: any) => acc + ci.assignedQty, 0);
                        const remaining = it.quantity - committed;
                        const isFullyAssigned = remaining <= 0;

                        return (
                          <div 
                            key={it.id} 
                            onClick={() => !isFullyAssigned && handleAddItem(it)}
                            className={`p-5 rounded-[1.5rem] border transition-all cursor-pointer flex justify-between items-center group ${
                              selectedItems.find(sel => sel.boqItemId === it.id) || isFullyAssigned
                                ? "bg-slate-800/30 border-slate-700/50 opacity-30 grayscale pointer-events-none" 
                                : "bg-slate-800/80 border-white/5 hover:border-blue-500/50 hover:bg-slate-700/50 hover:scale-[1.01]"
                            }`}
                          >
                            <div className="flex-1">
                              <div className="flex items-center gap-3 mb-1">
                                  <span className="px-2 py-0.5 rounded-md bg-slate-700 text-slate-400 font-mono text-[10px] uppercase">{it.itemCode}</span>
                                  <p className="text-white font-bold text-base">{it.description}</p>
                                  {isFullyAssigned && <span className="bg-rose-500/10 text-rose-500 text-[10px] px-2 py-0.5 rounded-full border border-rose-500/20">تم إسناده بالكامل</span>}
                              </div>
                              
                              <div className="flex items-center gap-4 mt-2">
                                <div className="text-[10px] text-slate-500">
                                   إجمالي المشروع: <span className="text-white font-mono">{it.quantity}</span>
                                </div>
                                <div className="text-[10px] text-amber-500/70">
                                   تم إسناده مسبقاً: <span className="text-amber-500 font-mono">{committed}</span>
                                </div>
                                <div className="text-[10px] text-emerald-500/70">
                                   المتبقي: <span className="text-emerald-500 font-mono font-bold">{remaining}</span>
                                </div>
                              </div>
                            </div>
                            <div className="mr-4">
                               {!isFullyAssigned && (
                                 <div className="w-10 h-10 rounded-2xl bg-blue-500/10 flex items-center justify-center text-blue-500 group-hover:bg-blue-500 group-hover:text-white transition-all shadow-soft font-bold text-xl">+</div>
                               )}
                            </div>
                          </div>
                        );
                      })
                    )}
                  </div>
                </motion.div>
              </div>
            )}

            <div className="space-y-4 border border-white/5 p-6 rounded-3xl bg-slate-900/50">
              <label className="text-sm font-bold text-amber-400 flex items-center gap-2">
                  <div className="w-1.5 h-1.5 rounded-full bg-amber-500" />
                  نسبة الدفعة المقدمة (%)
              </label>
              <input type="number" required min="0" max="100" value={formData.advancePayment} onChange={e => setFormData({...formData, advancePayment: Number(e.target.value)})} className="w-full bg-slate-900 border border-slate-700 rounded-xl py-3 px-4 text-white focus:outline-none focus:ring-2 focus:ring-amber-500/50 transition-all font-mono" />
            </div>

            <div className="space-y-4 border border-white/5 p-6 rounded-3xl bg-slate-900/50">
              <label className="text-sm font-bold text-rose-400 flex items-center gap-2">
                  <div className="w-1.5 h-1.5 rounded-full bg-rose-500" />
                  نسبة الخصم / المحتجز (%)
              </label>
              <input type="number" required min="0" max="100" value={formData.retentionPercent} onChange={e => setFormData({...formData, retentionPercent: Number(e.target.value)})} className="w-full bg-slate-900 border border-slate-700 rounded-xl py-3 px-4 text-white focus:outline-none focus:ring-2 focus:ring-rose-500/50 transition-all font-mono" />
            </div>
          </div>

          <div className="pt-6 border-t border-white/5 flex gap-4 justify-end items-center">
            {projects.length === 0 && (
              <span className="text-rose-400 text-sm font-medium ml-auto">
                يجب إنشاء مشروع أولاً قبل تسجيل العقد.
              </span>
            )}
            <button 
              type="submit" 
              disabled={isLoading || projects.length === 0} 
              className="flex items-center gap-2 px-8 py-2.5 rounded-xl font-medium bg-orange-600 hover:bg-orange-500 text-white shadow-[0_0_15px_rgba(249,115,22,0.3)] transition-all disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isLoading ? <Loader2 size={18} className="animate-spin" /> : <Save size={18} />}
              <span>حفظ واعتماد العقد</span>
            </button>
          </div>
        </form>
      </motion.div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter, useParams } from "next/navigation";
import { motion } from "framer-motion";
import {
  FileSignature, Save, ArrowRight, Loader2, PlusCircle,
  Crown, HardHat, Building2, Edit3, AlertTriangle, Plus, Printer
} from "lucide-react";
import axios from "axios";
import { API_BASE_URL } from "@/lib/api";
import { getApiErrorMessage } from "@/lib/apiErrors";
import { useDownloadPdf } from "@/hooks/useDownloadPdf";
import PrintHeader from "@/app/dashboard/components/PrintHeader";
import PrintFooter from "@/app/dashboard/components/PrintFooter";

export default function EditContractPage() {
  const router = useRouter();
  const params = useParams();
  const contractId = params.id as string;

  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [contract, setContract] = useState<any>(null);

  const { pdfRef, downloadPdf } = useDownloadPdf();
  const [projectBoq, setProjectBoq] = useState<any[]>([]);
  const [selectedItems, setSelectedItems] = useState<any[]>([]);
  const [showBoqSelector, setShowBoqSelector] = useState(false);

  const [formData, setFormData] = useState({
    projectId: "",
    type: "MAIN_CONTRACT",
    referenceNumber: "",
    retentionPercent: 5,
    advancePayment: 10,
    scope: "",
  });

  useEffect(() => {
    if (contractId) fetchContract();
  }, [contractId]);

  const fetchContract = async () => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get(`${API_BASE_URL}/v1/contracts/${contractId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      const c = res.data;
      setContract(c);
      setFormData({
        projectId: c.projectId || "",
        type: c.type || "MAIN_CONTRACT",
        referenceNumber: c.referenceNumber || "",
        retentionPercent: Number(c.retentionPercent) || 5,
        advancePayment: Number(c.advancePayment) || 10,
        scope: c.scope || "",
      });

      // Map existing items
      if (c.items && c.items.length > 0) {
        setSelectedItems(c.items.map((it: any) => ({
          boqItemId: it.boqItemId,
          description: it.boqItem?.description || "",
          unit: it.boqItem?.unit || "",
          assignedQty: Number(it.assignedQty),
          unitPrice: Number(it.unitPrice),
        })));
      }

      if (c.projectId) {
        fetchProjectBoq(c.projectId);
      }
    } catch (err) {
      alert("لم يتم العثور على العقد.");
      router.push("/dashboard/contracts");
    } finally {
      setIsLoading(false);
    }
  };

  const fetchProjectBoq = async (pid: string) => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get(`${API_BASE_URL}/v1/projects/${pid}/boq`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProjectBoq(res.data);
    } catch (err) {}
  };

  const handleAddItem = (item: any) => {
    if (selectedItems.find(it => it.boqItemId === item.id)) return;
    
    const committedToOthers = (item.contractItems || [])
      .filter((ci: any) => ci.contract?.type === formData.type && ci.contractId !== contractId)
      .reduce((acc: any, ci: any) => acc + Number(ci.assignedQty), 0);
    const remaining = Math.max(0, item.quantity - committedToOthers);

    const defaultPrice = formData.type === "SUBCONTRACT" ? (item.subcontractorPrice || 0) : item.unitPrice;

    setSelectedItems([...selectedItems, {
      boqItemId: item.id,
      description: item.description,
      unit: item.unit,
      assignedQty: remaining,
      unitPrice: defaultPrice, 
    }]);
    setShowBoqSelector(false);
  };

  const removeItem = (id: string) => {
    setSelectedItems(selectedItems.filter(it => it.boqItemId !== id));
  };

  const updateItemValue = (id: string, field: string, value: string) => {
    setSelectedItems(prev => prev.map(it => 
      it.boqItemId === id ? { ...it, [field]: value } : it
    ));
  };

  const calculatedTotal = selectedItems.reduce((acc, it) => acc + (Number(it.assignedQty) * Number(it.unitPrice)), 0);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      const token = localStorage.getItem("token");
      const payload: Record<string, unknown> = {
        referenceNumber: formData.referenceNumber,
        retentionPercent: formData.retentionPercent,
        advancePayment: formData.advancePayment,
        totalValue: calculatedTotal,
      };
      if (!hasInvoices) {
        payload.items = selectedItems;
      }

      await axios.patch(
        `${API_BASE_URL}/v1/contracts/${contractId}`,
        payload,
        { headers: { Authorization: `Bearer ${token}` } }
      );
      router.push("/dashboard/contracts");
    } catch (err: unknown) {
      alert(getApiErrorMessage(err, "خطأ أثناء حفظ التعديلات على العقد."));
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <Loader2 className="animate-spin text-orange-500" size={48} />
      </div>
    );
  }

  const hasInvoices = (contract?.invoices?.length || 0) > 0;
  const isMain = contract?.type === "MAIN_CONTRACT";
  const partyName = isMain
    ? (contract?.project?.client?.name || "الجهة المالكة (قيد التجهيز)")
    : (contract?.subcontractor?.name || "—");

  return (
    <>
    <div className="max-w-3xl mx-auto space-y-6 w-full animate-in fade-in zoom-in-95 duration-500 pb-12">
      {/* Header */}
      <div className="flex items-center gap-4">
        <button
          onClick={() => router.push("/dashboard/contracts")}
          className="p-2.5 rounded-xl bg-white/5 hover:bg-white/10 text-slate-300 transition-colors"
        >
          <ArrowRight size={20} />
        </button>
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center gap-3">
            <Edit3 className={isMain ? "text-indigo-400" : "text-amber-400"} size={24} />
            تعديل العقد
          </h1>
          <p className="text-slate-400 text-sm mt-1">
            تعديل البيانات المالية والمرجعية للعقد
          </p>
        </div>
        <button type="button" onClick={() => downloadPdf(`Contract_${contract?.referenceNumber || 'draft'}.pdf`)} className="flex items-center gap-2 px-5 py-2.5 bg-rose-800 hover:bg-rose-700 text-rose-300 rounded-xl transition-colors border border-rose-700 shadow-lg font-medium mr-auto">
          <Printer size={18} /> PDF
        </button>
      </div>

      {/* Contract Info Banner */}
      <div className={`rounded-2xl border p-4 flex items-center gap-4 ${
        isMain
          ? "bg-indigo-500/5 border-indigo-500/20"
          : "bg-amber-500/5 border-amber-500/20"
      }`}>
        <div className={`w-12 h-12 rounded-2xl flex items-center justify-center border ${
          isMain
            ? "bg-indigo-500/10 border-indigo-500/20 text-indigo-400"
            : "bg-amber-500/10 border-amber-500/20 text-amber-400"
        }`}>
          {isMain ? <Crown size={22} /> : <HardHat size={22} />}
        </div>
        <div>
          <div className={`text-xs font-bold mb-1 flex items-center gap-1.5 ${
            isMain ? "text-indigo-300" : "text-amber-300"
          }`}>
            {isMain ? "عقد رئيسي مع المالك — المستخلصات تُعد إيراداً" : "عقد مقاول باطن — المستخلصات تُعد تكلفة"}
          </div>
          <div className="flex items-center gap-2">
            {isMain ? <Building2 size={15} className="text-slate-400" /> : <HardHat size={15} className="text-slate-400" />}
            <span className="font-bold text-white">{partyName}</span>
            <span className="text-slate-500 font-mono text-sm">| REF: {contract?.referenceNumber}</span>
          </div>
          <p className="text-xs text-slate-500 mt-1">
            المشروع: {contract?.project?.name} ({contract?.project?.code})
          </p>
        </div>
      </div>

      {/* Warning if has invoices */}
      {hasInvoices && (
        <div className="bg-amber-500/5 border border-amber-500/20 rounded-2xl p-4 flex items-start gap-3">
          <AlertTriangle size={18} className="text-amber-400 shrink-0 mt-0.5" />
          <div>
            <p className="text-amber-300 font-bold text-sm">
              هذا العقد مرتبط بـ {contract.invoices.length} مستخلص — تعديل البنود غير مسموح
            </p>
            <p className="text-slate-400 text-xs mt-1">
              يمكنك تعديل الرقم المرجعي، نسبة الضمان، والدفعة المقدمة فقط. لحفظ بنود العقد يجب عدم وجود أي مستخلص.
            </p>
          </div>
        </div>
      )}

      {/* Form */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="glass-dark border border-white/5 rounded-3xl p-6 sm:p-8"
      >
        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Reference Number */}
            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-300">رقم العقد المرجعي (REF)</label>
              <input
                type="text"
                required
                value={formData.referenceNumber}
                onChange={e => setFormData({ ...formData, referenceNumber: e.target.value })}
                className="w-full bg-slate-900/50 border border-slate-800 rounded-xl py-3 px-4 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-orange-500/50 transition-all font-mono"
                dir="ltr"
              />
            </div>

            {/* No manual Total Value Input - Replaced by auto-calculation later */}

            {/* Retention */}
            <div className="space-y-2 border border-white/5 p-5 rounded-2xl bg-slate-900/40">
              <label className="text-sm font-bold text-rose-400 flex items-center gap-2">
                <div className="w-1.5 h-1.5 rounded-full bg-rose-500" />
                نسبة الاحتجاز / الضمان (%)
              </label>
              <input
                type="number"
                required
                min="0"
                max="100"
                value={formData.retentionPercent}
                onChange={e => setFormData({ ...formData, retentionPercent: Number(e.target.value) })}
                className="w-full bg-slate-900 border border-slate-800 rounded-xl py-3 px-4 text-white focus:outline-none focus:ring-2 focus:ring-rose-500/50 transition-all font-mono"
              />
            </div>

            {/* Advance Payment */}
            <div className="space-y-2 border border-white/5 p-5 rounded-2xl bg-slate-900/40">
              <label className="text-sm font-bold text-amber-400 flex items-center gap-2">
                <div className="w-1.5 h-1.5 rounded-full bg-amber-500" />
                نسبة الدفعة المقدمة (%)
              </label>
              <input
                type="number"
                required
                min="0"
                max="100"
                value={formData.advancePayment}
                onChange={e => setFormData({ ...formData, advancePayment: Number(e.target.value) })}
                className="w-full bg-slate-900 border border-slate-800 rounded-xl py-3 px-4 text-white focus:outline-none focus:ring-2 focus:ring-amber-500/50 transition-all font-mono"
              />
            </div>

            {/* Scope */}
            <div className="space-y-2 md:col-span-2">
              <label className="text-sm font-medium text-slate-300">نطاق العمل / وصف العقد</label>
              <textarea
                rows={4}
                value={formData.scope}
                onChange={e => setFormData({ ...formData, scope: e.target.value })}
                className="w-full bg-slate-900/50 border border-slate-800 rounded-xl py-3 px-4 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-orange-500/50 transition-all resize-y min-h-[100px]"
                placeholder="اكتب وصفاً لنطاق أعمال هذا العقد..."
              />
            </div>
          </div>

          {/* BOQ Selection Section */}
          <div className="space-y-4 border border-blue-500/30 p-5 rounded-3xl bg-blue-500/5">
            <div className="flex items-center justify-between mb-2">
              <label className="text-sm font-bold text-blue-400 flex items-center gap-2">
                 <div className="w-2 h-2 rounded-full bg-blue-500 animate-pulse" />
                 بنود وجدول كميات العقد (Scope of Work)
              </label>
              <button 
                type="button"
                disabled={hasInvoices}
                onClick={() => setShowBoqSelector(true)}
                className="px-4 py-1.5 bg-blue-600 hover:bg-blue-500 text-white text-xs font-bold rounded-xl transition-all shadow-lg flex items-center gap-2 disabled:opacity-40 disabled:cursor-not-allowed"
              >
                <span className="text-lg">+</span> إضافة بند من المشروع
              </button>
            </div>

            {selectedItems.length === 0 ? (
              <div className="py-10 text-center text-slate-500 border-2 border-dashed border-white/5 rounded-2xl">
                لم يتم إضافة بنود للعقد بعد. اضغط على زر الإضافة لاختيار مهام من جدول كميات المشروع.
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-right text-xs text-slate-300">
                  <thead className="border-b border-white/10 uppercase font-bold text-[10px] text-slate-500">
                    <tr>
                      <th className="pb-3 pr-2">وصف البند</th>
                      <th className="pb-3 text-center">الكمية المسندة</th>
                      <th className="pb-3 text-center">السعر (الوحدة)</th>
                      <th className="pb-3 text-left">إجمالي البند</th>
                      <th className="pb-3 text-center w-10">#</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-white/5">
                    {selectedItems.map((it) => (
                      <tr key={it.boqItemId} className="group transition-colors hover:bg-white/5">
                        <td className="py-4 pr-2">
                          <p className="font-bold text-white mb-0.5">{it.description}</p>
                          <p className="text-[10px] text-slate-500 font-mono italic">Unit: {it.unit}</p>
                        </td>
                        <td className="py-4 text-center">
                          <input 
                            type="number" 
                            disabled={hasInvoices}
                            value={it.assignedQty} 
                            onChange={e => updateItemValue(it.boqItemId, 'assignedQty', e.target.value)}
                            className="w-20 bg-slate-900 border border-slate-700 rounded-lg text-center py-1.5 font-mono text-emerald-400 focus:outline-none focus:border-emerald-500/50 transition-all disabled:opacity-50"
                          />
                        </td>
                        <td className="py-4 text-center">
                          <input 
                            type="number" 
                            disabled={hasInvoices}
                            value={it.unitPrice} 
                            onChange={e => updateItemValue(it.boqItemId, 'unitPrice', e.target.value)}
                            className="w-24 bg-slate-900 border border-slate-700 rounded-lg text-center py-1.5 font-mono text-blue-400 focus:outline-none focus:border-blue-500/50 transition-all disabled:opacity-50"
                          />
                        </td>
                        <td className="py-4 text-left font-mono font-bold text-white text-[13px]">
                          {(Number(it.assignedQty) * Number(it.unitPrice)).toLocaleString(undefined, {minimumFractionDigits: 2})}
                        </td>
                        <td className="py-4 text-center">
                          <button type="button" disabled={hasInvoices} onClick={() => removeItem(it.boqItemId)} className="p-1.5 text-slate-600 hover:text-rose-500 hover:bg-rose-500/10 rounded-lg transition-all disabled:opacity-30 disabled:cursor-not-allowed">
                            ✕
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                  <tfoot>
                    <tr className="border-t border-blue-500/20">
                      <td colSpan={3} className="py-5 text-left font-bold text-slate-400">إجمالي قيمة العقد (تلقائي):</td>
                      <td className="py-5 text-left font-mono font-black text-blue-400 text-xl">
                        <span className="text-xs text-slate-500 mr-1">SAR</span>
                        {calculatedTotal.toLocaleString(undefined, {minimumFractionDigits: 2})}
                      </td>
                      <td></td>
                    </tr>
                  </tfoot>
                </table>
              </div>
            )}
          </div>

          {/* BOQ Selector Modal */}
          {showBoqSelector && (
            <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md">
              <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="bg-slate-900 border border-white/10 w-full max-w-3xl rounded-[2.5rem] p-8 shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 w-64 h-64 bg-blue-500/5 rounded-full blur-[80px] -z-10" />
                
                <div className="flex justify-between items-center mb-8">
                  <div>
                      <h3 className="text-2xl font-black text-white">جدول كميات المشروع</h3>
                      <p className="text-sm text-slate-400 mt-1">اختر البنود التي تود إسنادها لهذا المقاول</p>
                  </div>
                  <button type="button" onClick={() => setShowBoqSelector(false)} className="w-10 h-10 flex items-center justify-center rounded-2xl bg-white/5 text-slate-400 hover:text-white transition-colors">✕</button>
                </div>
                
                <div className="max-h-[450px] overflow-y-auto space-y-3 pr-4 custom-scrollbar">
                  {projectBoq.length === 0 ? (
                    <div className="text-center py-20 text-slate-500 flex flex-col items-center gap-4">
                       <div className="p-4 rounded-full bg-white/5"><Loader2 className="animate-spin text-slate-400" /></div>
                       <p>لا توجد بنود متاحة حالياً في المشروع.</p>
                    </div>
                  ) : (
                    projectBoq.map(it => {
                      const committed = (it.contractItems || [])
                        .filter((ci: any) => ci.contract?.type === formData.type && ci.contractId !== contractId)
                        .reduce((acc: number, ci: any) => acc + ci.assignedQty, 0);
                      const remaining = it.quantity - committed;
                      const isFullyAssigned = remaining <= 0;

                      return (
                        <div 
                          key={it.id} 
                          onClick={() => !isFullyAssigned && handleAddItem(it)}
                          className={`p-5 rounded-[1.5rem] border transition-all cursor-pointer flex justify-between items-center group ${
                            selectedItems.find(sel => sel.boqItemId === it.id) || isFullyAssigned
                              ? "bg-slate-800/30 border-slate-700/50 opacity-30 grayscale pointer-events-none" 
                              : "bg-slate-800/80 border-white/5 hover:border-blue-500/50 hover:bg-slate-700/50 hover:scale-[1.01]"
                          }`}
                        >
                          <div className="flex-1">
                            <div className="flex items-center gap-3 mb-1">
                                <span className="px-2 py-0.5 rounded-md bg-slate-700 text-slate-400 font-mono text-[10px] uppercase">{it.itemCode}</span>
                                <p className="text-white font-bold text-base">{it.description}</p>
                                {isFullyAssigned && <span className="bg-rose-500/10 text-rose-500 text-[10px] px-2 py-0.5 rounded-full border border-rose-500/20">تم إسناده بالكامل</span>}
                            </div>
                            
                            <div className="flex items-center gap-4 mt-2">
                              <div className="text-[10px] text-slate-500">
                                 إجمالي المشروع: <span className="text-white font-mono">{it.quantity}</span>
                              </div>
                              <div className="text-[10px] text-amber-500/70">
                                 تم إسناده لمقاولين آخرين: <span className="text-amber-500 font-mono">{committed}</span>
                              </div>
                              <div className="text-[10px] text-emerald-500/70">
                                 المتاح للإسناد: <span className="text-emerald-500 font-mono font-bold">{remaining}</span>
                              </div>
                            </div>
                          </div>
                          <div className="mr-4">
                             {!isFullyAssigned && (
                               <div className="w-10 h-10 rounded-2xl bg-blue-500/10 flex items-center justify-center text-blue-500 group-hover:bg-blue-500 group-hover:text-white transition-all shadow-soft font-bold text-xl">+</div>
                             )}
                          </div>
                        </div>
                      );
                    })
                  )}
                </div>
              </motion.div>
            </div>
          )}

          <div className="pt-6 border-t border-white/5 flex gap-4 justify-end">
            <button
              type="button"
              onClick={() => router.push("/dashboard/contracts")}
              className="px-6 py-2.5 rounded-xl font-medium bg-white/5 hover:bg-white/10 text-slate-300 transition-all"
            >
              إلغاء
            </button>
            <button
              type="submit"
              disabled={isSaving}
              className={`flex items-center gap-2 px-8 py-2.5 rounded-xl font-bold transition-all disabled:opacity-50 text-white shadow-lg ${
                isMain
                  ? "bg-indigo-600 hover:bg-indigo-500 shadow-indigo-500/30"
                  : "bg-orange-600 hover:bg-orange-500 shadow-orange-500/30"
              }`}
            >
              {isSaving ? <Loader2 size={18} className="animate-spin" /> : <Save size={18} />}
              حفظ التعديلات
            </button>
          </div>
        </form>
      </motion.div>

      {/* Change Orders Section */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.1 }}
        className="glass-dark border border-white/5 rounded-3xl p-6 sm:p-8 relative"
      >
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 mb-6">
          <div>
            <h2 className="text-xl font-bold flex items-center gap-3 text-white">
               <div className="p-2 bg-emerald-500/10 rounded-xl text-emerald-400">
                 <FileSignature size={20} />
               </div>
               الملاحق والأوامر التغييرية
            </h2>
            <p className="text-sm text-slate-400 mt-2">
              إدارة التعديلات المالية على هذا العقد من زيادات (Variation Orders) أو تنزيلات
            </p>
          </div>
          
          <button
            onClick={() => router.push(`/dashboard/contracts/${contractId}/change-orders/create`)}
            className="flex items-center justify-center gap-2 px-6 py-3 rounded-xl font-bold bg-gradient-to-r from-emerald-600 to-teal-500 hover:from-emerald-500 hover:to-teal-400 text-white shadow-lg shadow-emerald-500/30 hover:-translate-y-0.5 transition-all w-full sm:w-auto"
          >
            <PlusCircle size={20} />
            إنشاء ملحق جديد
          </button>
        </div>

        <div className="overflow-x-auto rounded-2xl border border-white/5 bg-slate-900/30">
          <table className="w-full text-right text-sm">
            <thead className="bg-slate-900/80 text-slate-400 font-semibold border-b border-white/10">
              <tr>
                <th className="px-4 py-4 whitespace-nowrap">المرجع</th>
                <th className="px-4 py-4">العنوان</th>
                <th className="px-4 py-4">النوع</th>
                <th className="px-4 py-4 whitespace-nowrap">القيمة (SAR)</th>
                <th className="px-4 py-4">تاريخ الإصدار</th>
                <th className="px-4 py-4 text-center">الحالة</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/5 text-slate-300">
               {(!contract?.changeOrders || contract.changeOrders.length === 0) ? (
                 <tr>
                    <td colSpan={6} className="px-4 py-16 text-center">
                      <div className="flex flex-col items-center justify-center text-slate-500 gap-3">
                        <FileSignature size={36} className="opacity-20" />
                        <p>لا توجد ملاحق مسجلة لهذا العقد حتى الآن.</p>
                      </div>
                    </td>
                 </tr>
               ) : (
                 contract.changeOrders.map((co: any) => (
                   <tr key={co.id} className="hover:bg-slate-800/40 transition-colors">
                     <td className="px-4 py-4 font-mono font-bold text-white">#{co.orderNumber}</td>
                     <td className="px-4 py-4 font-medium max-w-[200px] truncate" title={co.title}>{co.title}</td>
                     <td className="px-4 py-4">
                       <span className={`px-2 py-1 rounded-md text-xs font-bold ${co.type === 'ADDITION' ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : 'bg-rose-500/10 text-rose-400 border border-rose-500/20'}`}>
                         {co.type === 'ADDITION' ? 'بند إضافي (+)' : 'خصم متفق (-)'}
                       </span>
                     </td>
                     <td className={`px-4 py-4 font-mono font-bold ${co.type === 'DEDUCTION' ? 'text-rose-400' : 'text-emerald-400'}`}>
                       {co.type === 'DEDUCTION' ? '-' : ''}{Number(co.amount).toLocaleString('en-US')}
                     </td>
                     <td className="px-4 py-4 font-mono text-slate-400">
                       {new Date(co.issueDate).toLocaleDateString('ar-SA')}
                     </td>
                     <td className="px-4 py-4 text-center">
                       <span className={`px-2 py-1 rounded-md text-xs font-bold ${co.status === 'APPROVED' ? 'bg-blue-500/10 text-blue-400 border border-blue-500/20' : 'bg-slate-800 text-slate-300 border border-slate-700'}`}>
                         {co.status === 'APPROVED' ? 'معتمد ومؤثر' : 'مسودة'}
                       </span>
                     </td>
                   </tr>
                 ))
               )}
            </tbody>
          </table>
        </div>
      </motion.div>
    </div>

      {/* Print View */}
      <div ref={pdfRef} className="hidden print:block print-on-letterhead print:!text-black font-sans" dir="rtl">
        <PrintHeader />
        <div className="mb-6">
          <div className="inline-block bg-slate-50 p-3 rounded-lg border border-slate-200">
            <p className="text-sm font-bold text-slate-800">رقم العقد (Ref): <span className="font-mono text-indigo-700">{contract?.referenceNumber}</span></p>
          </div>
          <h1 className="text-2xl font-black text-slate-900 mt-3">
            {isMain ? 'عقد رئيسي - Main Contract' : 'عقد مقاول باطن - Subcontract'}
          </h1>
        </div>
        <div className="grid grid-cols-2 gap-6 mb-6 text-sm">
          <div className="bg-white p-4 border-2 border-slate-200 rounded-lg shadow-sm">
            <p className="text-slate-500 font-bold mb-2 uppercase text-xs tracking-wider border-b border-slate-100 pb-2">الطرف الثاني (Party):</p>
            <p className="font-black text-lg text-slate-900">{partyName}</p>
          </div>
          <div className="bg-white p-4 border-2 border-slate-200 rounded-lg shadow-sm">
            <p className="text-slate-500 font-bold mb-2 uppercase text-xs tracking-wider border-b border-slate-100 pb-2">المشروع (Project):</p>
            <p className="font-bold text-lg text-slate-900">{contract?.project?.name}</p>
            <p className="font-mono text-sm text-slate-500">{contract?.project?.code}</p>
          </div>
        </div>
        <div className="grid grid-cols-3 gap-4 mb-6 text-sm">
          <div className="bg-slate-50 p-3 rounded border border-slate-200">
            <span className="font-bold text-slate-500">قيمة العقد: </span>
            <span className="font-mono font-black">{calculatedTotal.toLocaleString()} SAR</span>
          </div>
          <div className="bg-slate-50 p-3 rounded border border-slate-200">
            <span className="font-bold text-slate-500">نسبة الضمان: </span>
            <span className="font-mono font-black">{formData.retentionPercent}%</span>
          </div>
          <div className="bg-slate-50 p-3 rounded border border-slate-200">
            <span className="font-bold text-slate-500">الدفعة المقدمة: </span>
            <span className="font-mono font-black">{formData.advancePayment}%</span>
          </div>
        </div>
        {selectedItems.length > 0 && (
          <div className="mb-6">
            <h3 className="font-bold text-slate-800 text-sm mb-2 border-b border-slate-200 pb-1">بنود العقد (Contract Items):</h3>
            <table className="w-full text-right text-sm border-collapse">
              <thead>
                <tr className="bg-slate-900 text-white">
                  <th className="p-2 border border-slate-900">البيان</th>
                  <th className="p-2 border border-slate-900 text-center w-16">الوحدة</th>
                  <th className="p-2 border border-slate-900 text-center w-20">الكمية</th>
                  <th className="p-2 border border-slate-900 text-center w-24">سعر الوحدة</th>
                  <th className="p-2 border border-slate-900 text-center w-28">الإجمالي</th>
                </tr>
              </thead>
              <tbody>
                {selectedItems.map((item, i) => (
                  <tr key={i} className="border-b border-slate-300">
                    <td className="p-2 border-x border-slate-300 font-bold">{item.description}</td>
                    <td className="p-2 border-x border-slate-300 text-center">{item.unit}</td>
                    <td className="p-2 border-x border-slate-300 text-center font-mono">{item.assignedQty}</td>
                    <td className="p-2 border-x border-slate-300 text-center font-mono">{Number(item.unitPrice).toLocaleString()}</td>
                    <td className="p-2 border-x border-slate-300 text-center font-mono font-black">{(Number(item.assignedQty) * Number(item.unitPrice)).toLocaleString()}</td>
                  </tr>
                ))}
              </tbody>
              <tfoot>
                <tr className="bg-slate-900 text-white font-bold">
                  <td colSpan={4} className="p-2 border border-slate-900 text-left">الإجمالي الكلي</td>
                  <td className="p-2 border border-slate-900 text-center font-mono">{calculatedTotal.toLocaleString()}</td>
                </tr>
              </tfoot>
            </table>
          </div>
        )}
        {formData.scope && (
          <div className="mb-6">
            <h3 className="font-bold text-slate-800 text-sm mb-2 border-b border-slate-200 pb-1">نطاق العمل (Scope):</h3>
            <p className="text-sm text-slate-700 whitespace-pre-wrap bg-slate-50 p-3 rounded border border-slate-200">{formData.scope}</p>
          </div>
        )}
        <div className="fixed bottom-0 left-0 w-full bg-white px-8 pb-2">
          <PrintFooter />
        </div>
      </div>
    </>
  );
}

