import { exportToCsv } from "@/lib/exportUtils";
import { resolveBillingMode, qtyToProgressPercent } from "@/lib/billingMode";
import { useDownloadPdf } from "@/hooks/useDownloadPdf";

function getLineContractQty(detail: any, invoice: any) {
  const ci = invoice?.contract?.items?.find((x: any) => x.boqItemId === detail.boqItemId);
  return Number(ci?.assignedQty ?? detail.boqItem?.quantity ?? 1);
}

function formatDetailProgress(
  detail: any,
  field: "previousQty" | "currentQty" | "totalQty",
  invoice?: any,
) {
  const mode = resolveBillingMode(detail.boqItem || {});
  const qty = Number(detail[field] ?? 0);
  const contractQty = getLineContractQty(detail, invoice);
  if (mode === "LUMP_SUM_PROGRESS") {
    if (field === "currentQty" && detail.currentProgressPercent != null) {
      return `${Number(detail.currentProgressPercent).toFixed(1)}%`;
    }
    return `${qtyToProgressPercent(qty, contractQty).toFixed(1)}%`;
  }
  return qty;
}
import PrintHeader from "../../components/PrintHeader";
import PrintFooter from "../../components/PrintFooter";
import PrintLetterhead from "../../components/PrintLetterhead";

export default function InvoiceViewPage() {
  const router = useRouter();
  const params = useParams();
  const invoiceId = params.id as string;
  const [invoice, setInvoice] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isPosting, setIsPosting] = useState(false);
  const [userPerms, setUserPerms] = useState<string[]>([]);
  const [userRole, setUserRole] = useState("");
  const { pdfRef, downloadPdf } = useDownloadPdf();

  useEffect(() => {
    const userStr = localStorage.getItem("user");
    if (userStr) {
      try {
        const u = JSON.parse(userStr);
        setUserPerms(u.permissions || []);
        setUserRole(u.role || "");
      } catch (e) {}
    }
    if (invoiceId) fetchInvoice();
  }, [invoiceId]);

  const hasPermission = (perm: string) => {
    if (userRole === "Admin" || userRole === "System Admin") return true;
    return userPerms.includes(perm);
  };

  const fetchInvoice = async () => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get(`${API_BASE_URL}/v1/invoices/${invoiceId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setInvoice(res.data);
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSyncPayment = async () => {
    setIsSyncing(true);
    try {
      const token = localStorage.getItem("token");
      await axios.post(`${API_BASE_URL}/v1/invoices/${invoiceId}/sync-payment`, {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      await fetchInvoice();
      alert('تم تحديث حالة السداد من دفترة بنجاح!');
    } catch (err: any) {
      const msg = err.response?.data?.message || err.message || "خطأ مجهول";
      alert(`فشل المزامنة مع دفترة: ${msg}`);
      // If reverted to DRAFT, reload to show new status
      await fetchInvoice();
    } finally {
      setIsSyncing(false);
    }
  };



  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh]">
        <Loader2 className="animate-spin text-emerald-500 mb-4" size={48} />
        <p className="text-slate-400">جاري تحميل بيانات المستخلص...</p>
      </div>
    );
  }

  if (!invoice) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh]">
        <AlertCircle className="text-rose-500 mb-4" size={48} />
        <p className="text-slate-400">عذراً، المستخلص غير موجود أو حدث خطأ.</p>
        <button onClick={() => router.back()} className="mt-4 text-emerald-500 hover:underline">العودة للسابق</button>
      </div>
    );
  }

  const statusMap: Record<string, { label: string, color: string, bg: string, icon: any }> = {
    DRAFT: { label: "مسودة غير معتمدة", color: "text-amber-400", bg: "bg-amber-500/10 border-amber-500/20", icon: Clock },
    CERTIFIED: { label: "مستخلص معتمد", color: "text-blue-400", bg: "bg-blue-500/10 border-blue-500/20", icon: FileText },
