                 <div key={index} className="grid grid-cols-12 gap-3 items-center bg-slate-950/50 p-3 rounded-xl border border-white/5 relative group">
                   <div className="col-span-4">
                     <input type="text" required placeholder="المهنة (نجار، حداد...)" value={labor.trade} onChange={e => {
                       const newLabors = [...labors]; newLabors[index].trade = e.target.value; setLabors(newLabors);
                     }} className="w-full bg-slate-900 border border-slate-800 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-blue-500" />
                   </div>
                   <div className="col-span-3">
                     <input type="number" required min="1" placeholder="العدد" value={labor.count} onChange={e => {
                       const newLabors = [...labors]; newLabors[index].count = parseInt(e.target.value); setLabors(newLabors);
                     }} className="w-full bg-slate-900 border border-slate-800 rounded-lg px-3 py-2 text-sm text-center font-mono text-white focus:outline-none focus:border-blue-500" />
                   </div>
                   <div className="col-span-3">
                     <input type="number" required min="1" step="0.5" placeholder="ساعات" value={labor.hours} onChange={e => {
                       const newLabors = [...labors]; newLabors[index].hours = parseFloat(e.target.value); setLabors(newLabors);
                     }} className="w-full bg-slate-900 border border-slate-800 rounded-lg px-3 py-2 text-sm text-center font-mono text-white focus:outline-none focus:border-blue-500" />
                   </div>
                   <div className="col-span-2 flex justify-center">
                     <button type="button" onClick={() => handleRemoveLabor(index)} className="p-2 text-slate-500 hover:text-rose-500 hover:bg-rose-500/10 rounded-lg transition-colors">
                       <Trash2 size={16} />
                     </button>
                   </div>
                 </div>
               ))}
               {labors.length === 0 && <p className="text-xs text-center text-slate-500 py-4">لم يتم إضافة عمالة بعد.</p>}
             </div>
          </div>

          {/* Equipments */}
          <div className="glass-dark border border-white/10 rounded-3xl p-6 shadow-xl bg-slate-900/60">
             <div className="flex justify-between items-center mb-6 border-b border-white/5 pb-4">
               <h2 className="text-base font-bold text-white flex items-center gap-2">
                 <HardHat className="text-amber-500" size={18} /> المعدات والآليات (المملوكة/المستأجرة)
               </h2>
               <button type="button" onClick={handleAddEquipment} className="text-xs font-bold bg-amber-500/10 text-amber-500 hover:bg-amber-500 hover:text-white px-3 py-1.5 rounded-lg border border-amber-500/20 transition-colors flex items-center gap-1">
                 <Plus size={14} /> إضافة معدة
               </button>
             </div>

             <div className="space-y-4">
               {equipments.map((equip, index) => (
                 <div key={index} className="grid grid-cols-12 gap-3 items-center bg-slate-950/50 p-3 rounded-xl border border-white/5 relative group">
                   <div className="col-span-4">
                     <input type="text" required placeholder="نوع المعدة (بوكلين...)" value={equip.equipmentType} onChange={e => {
                       const newEq = [...equipments]; newEq[index].equipmentType = e.target.value; setEquipments(newEq);
                     }} className="w-full bg-slate-900 border border-slate-800 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-amber-500" />
                   </div>
                   <div className="col-span-3">
                     <input type="number" required min="1" placeholder="العدد" value={equip.count} onChange={e => {
                       const newEq = [...equipments]; newEq[index].count = parseInt(e.target.value); setEquipments(newEq);
                     }} className="w-full bg-slate-900 border border-slate-800 rounded-lg px-3 py-2 text-sm text-center font-mono text-white focus:outline-none focus:border-amber-500" />
                   </div>
                   <div className="col-span-3">
                     <input type="number" required min="1" step="0.5" placeholder="ساعات" value={equip.hours} onChange={e => {
                       const newEq = [...equipments]; newEq[index].hours = parseFloat(e.target.value); setEquipments(newEq);
                     }} className="w-full bg-slate-900 border border-slate-800 rounded-lg px-3 py-2 text-sm text-center font-mono text-white focus:outline-none focus:border-amber-500" />
                   </div>
                   <div className="col-span-2 flex justify-center">
                     <button type="button" onClick={() => handleRemoveEquipment(index)} className="p-2 text-slate-500 hover:text-rose-500 hover:bg-rose-500/10 rounded-lg transition-colors">
                       <Trash2 size={16} />
                     </button>
                   </div>
                 </div>
               ))}
               {equipments.length === 0 && <p className="text-xs text-center text-slate-500 py-4">لم يتم إضافة آليات بعد.</p>}
             </div>
          </div>
        </div>

        <div className="glass-dark border border-white/10 rounded-3xl p-8 shadow-xl bg-slate-900/60 space-y-6">
          <div>
            <label className="text-sm font-bold text-white mb-3 block flex items-center gap-2">
              الأعمال المنجزة اليوم بالموقع (Work Performed)
            </label>
            <textarea 
              required
              rows={4}
              value={workPerformed}
              onChange={e => setWorkPerformed(e.target.value)}
              className="w-full bg-slate-950 border border-slate-800 rounded-2xl p-4 text-white focus:outline-none focus:border-amber-500 focus:ring-1 focus:ring-amber-500 text-sm leading-relaxed resize-none"
              placeholder="اكتب هنا تفاصيل الأعمال التي تمت اليوم في الموقع، مثل: صب قواعد القطاع أ، توريد 50 طن حديد..."
            />
          </div>
          <div>
            <label className="text-sm font-bold text-white mb-3 block flex items-center gap-2">
              ملاحظات الأمن والسلامة ومعوقات العمل (إن وجدت)
            </label>
            <textarea 
              rows={3}
              value={safetyNotes}
              onChange={e => setSafetyNotes(e.target.value)}
              className="w-full bg-slate-950 border border-slate-800 rounded-2xl p-4 text-white focus:outline-none focus:border-rose-500 focus:ring-1 focus:ring-rose-500 text-sm leading-relaxed resize-none"
              placeholder="تسجيل إصابات، تأخير في التوريد، طقس سيء عطل العمل..."
            />
          </div>
        </div>

        <button 
          type="submit" 
          disabled={isSubmitting}
          className="w-full flex justify-center items-center gap-2 px-6 py-5 rounded-2xl font-black text-lg bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-400 hover:to-orange-400 text-slate-900 shadow-[0_0_30px_rgba(245,158,11,0.2)] hover:shadow-[0_0_40px_rgba(245,158,11,0.4)] transition-all hover:-translate-y-1 disabled:opacity-50 disabled:cursor-not-allowed group"
        >
          {isSubmitting ? <Loader2 size={24} className="animate-spin" /> : <Save size={24} className="group-hover:scale-110 transition-transform" />}
          حفظ ورفع التقرير اليومي للإدارة
        </button>

      </form>

      {/* Print View */}
      <div ref={pdfRef} className="hidden print:block print:!bg-white print:!text-black font-sans p-8" dir="rtl">
        <PrintHeader />
        <div className="text-center mb-6 border-b-2 border-slate-900 pb-4">
          <h1 className="text-2xl font-black text-slate-900">تقرير الموقع اليومي</h1>
          <h2 className="text-sm text-slate-500 font-bold">Daily Progress Report (DPR)</h2>
        </div>
        <div className="grid grid-cols-3 gap-4 mb-6 text-sm">
          <div className="bg-slate-50 p-3 rounded border border-slate-200">
            <span className="font-bold text-slate-500">التاريخ: </span>
            <span className="font-mono font-bold">{reportDate}</span>
          </div>
          <div className="bg-slate-50 p-3 rounded border border-slate-200">
            <span className="font-bold text-slate-500">الطقس: </span>
            <span className="font-bold">{weather}</span>
          </div>
          <div className="bg-slate-50 p-3 rounded border border-slate-200">
            <span className="font-bold text-slate-500">درجة الحرارة: </span>
            <span className="font-mono font-bold">{temperature}°C</span>
          </div>
        </div>
        <div className="mb-6">
          <h3 className="font-bold text-slate-800 text-sm mb-2 border-b border-slate-200 pb-1">الأعمال المنجزة (Work Performed):</h3>
          <p className="text-sm text-slate-700 whitespace-pre-wrap bg-slate-50 p-3 rounded border border-slate-200">{workPerformed}</p>
        </div>
        {safetyNotes && (
          <div className="mb-6">
            <h3 className="font-bold text-slate-800 text-sm mb-2 border-b border-slate-200 pb-1">ملاحظات الأمن والسلامة (Safety Notes):</h3>
            <p className="text-sm text-slate-700 whitespace-pre-wrap bg-slate-50 p-3 rounded border border-slate-200">{safetyNotes}</p>
          </div>
        )}
        {labors.length > 0 && (
          <div className="mb-6">
            <h3 className="font-bold text-slate-800 text-sm mb-2 border-b border-slate-200 pb-1">العمالة (Labors):</h3>
            <table className="w-full text-right text-sm border-collapse">
              <thead><tr className="bg-slate-900 text-white"><th className="p-2 border border-slate-900">المهنة</th><th className="p-2 border border-slate-900 text-center w-20">العدد</th><th className="p-2 border border-slate-900 text-center w-20">الساعات</th><th className="p-2 border border-slate-900">ملاحظات</th></tr></thead>
              <tbody>{labors.map((l, i) => (
                <tr key={i} className="border-b border-slate-300">
                  <td className="p-2 border-x border-slate-300 font-bold">{l.trade}</td>
                  <td className="p-2 border-x border-slate-300 text-center font-mono">{l.count}</td>
                  <td className="p-2 border-x border-slate-300 text-center font-mono">{l.hours}</td>
                  <td className="p-2 border-x border-slate-300">{l.notes}</td>
                </tr>
              ))}</tbody>
            </table>
          </div>
        )}
        {equipments.length > 0 && (
          <div className="mb-6">
            <h3 className="font-bold text-slate-800 text-sm mb-2 border-b border-slate-200 pb-1">المعدات (Equipments):</h3>
            <table className="w-full text-right text-sm border-collapse">
              <thead><tr className="bg-slate-900 text-white"><th className="p-2 border border-slate-900">نوع المعدة</th><th className="p-2 border border-slate-900 text-center w-20">العدد</th><th className="p-2 border border-slate-900 text-center w-20">الساعات</th><th className="p-2 border border-slate-900">ملاحظات</th></tr></thead>
              <tbody>{equipments.map((e, i) => (
                <tr key={i} className="border-b border-slate-300">
                  <td className="p-2 border-x border-slate-300 font-bold">{e.equipmentType}</td>
                  <td className="p-2 border-x border-slate-300 text-center font-mono">{e.count}</td>
                  <td className="p-2 border-x border-slate-300 text-center font-mono">{e.hours}</td>
                  <td className="p-2 border-x border-slate-300">{e.notes}</td>
                </tr>
              ))}</tbody>
            </table>
          </div>
        )}
        <div className="fixed bottom-0 left-0 w-full bg-white px-8 pb-2">
          <PrintFooter />
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import axios from "axios";
import { useParams, useRouter } from "next/navigation";
import { API_BASE_URL } from "@/lib/api";
import { motion, AnimatePresence } from "framer-motion";
import { 
  Building2, 
  ArrowRight, 
  Calendar,
  User,
  Activity,
  HardHat,
  CheckCircle2,
  Clock,
  Wallet,
  FileSignature,
  ClipboardList,
  PieChart,
  Loader2,
  TrendingDown,
  TrendingUp,
  AlertCircle,
  Plus,
  X,
  FileText,
  Edit,
  Trash2
} from "lucide-react";
import Link from "next/link";

export default function ProjectDashboardPage() {
  const params = useParams();
  const router = useRouter();
  const projectId = params.id as string;
  
  const [project, setProject] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<'OVERVIEW' | 'BOQ' | 'CONTRACTS' | 'DAFTRA' | 'DPR'>('OVERVIEW');

  // BOQ ADD STATE
  const [isBoqModalOpen, setIsBoqModalOpen] = useState(false);
  const [isSubmittingBoq, setIsSubmittingBoq] = useState(false);
  const [newBoq, setNewBoq] = useState({ itemCode: '', description: '', unit: 'م٢', quantity: 1, unitPrice: 0 });
  const [isEditingBoq, setIsEditingBoq] = useState(false);
  const [editingBoqId, setEditingBoqId] = useState("");

  useEffect(() => {
    if (projectId) fetchProjectDetails();
  }, [projectId]);

  const fetchProjectDetails = async () => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get(`${API_BASE_URL}/v1/projects/${projectId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProject(res.data);
    } catch (err) {
      console.error(err);
      alert("استحالة الوصول للمشروع، الرجاء المحاولة مجدداً.");
      router.push('/dashboard/projects');
    } finally {
      setIsLoading(false);
    }
  };

  const handleAddBoq = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmittingBoq(true);
    try {
      const token = localStorage.getItem("token");
      if (isEditingBoq) {
        await axios.patch(`${API_BASE_URL}/v1/projects/${projectId}/boq/${editingBoqId}`, newBoq, {
          headers: { Authorization: `Bearer ${token}` }
        });
      } else {
        await axios.post(`${API_BASE_URL}/v1/projects/${projectId}/boq`, newBoq, {
          headers: { Authorization: `Bearer ${token}` }
        });
      }
      closeBoqModal();
      fetchProjectDetails(); // Refresh the table automatically
    } catch (err) {
      console.error(err);
      alert("حدث خطأ أثناء حفظ البند.");
    } finally {
      setIsSubmittingBoq(false);
    }
  };

  const handleEditBoqClick = (item: any) => {
    setNewBoq({
      itemCode: item.itemCode || '',
      description: item.description || '',
      unit: item.unit || 'م٢',
      quantity: item.quantity || 1,
      unitPrice: item.unitPrice || 0
    });
    setEditingBoqId(item.id);
    setIsEditingBoq(true);
    setIsBoqModalOpen(true);
  };

  const handleDeleteBoqItem = async (id: string) => {
    if (!window.confirm("هل أنت متأكد من حذف هذا البند؟")) return;
    try {
      const token = localStorage.getItem("token");
      await axios.delete(`${API_BASE_URL}/v1/projects/${projectId}/boq/${id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      fetchProjectDetails();
    } catch (err) {
      alert("خطأ أثناء حذف البند");
    }
  };

  const closeBoqModal = () => {
    setIsBoqModalOpen(false);
    setIsEditingBoq(false);
    setEditingBoqId("");
    setNewBoq({ itemCode: '', description: '', unit: 'م٢', quantity: 1, unitPrice: 0 });
  };

  const statusMap: Record<string, any> = {
    PLANNING: { label: "قيد التخطيط", color: "text-amber-400", border: "border-amber-500/30", bg: "bg-amber-500/10", glow: "from-amber-500/20", icon: Clock },
    ACTIVE: { label: "نشط (قيد التنفيذ)", color: "text-blue-400", border: "border-blue-500/30", bg: "bg-blue-500/10", glow: "from-blue-500/20", icon: HardHat },
    COMPLETED: { label: "مكتمل", color: "text-emerald-400", border: "border-emerald-500/30", bg: "bg-emerald-500/10", glow: "from-emerald-500/20", icon: CheckCircle2 },
    ON_HOLD: { label: "متوقف", color: "text-rose-400", border: "border-rose-500/30", bg: "bg-rose-500/10", glow: "from-rose-500/20", icon: Activity },
  };

  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[70vh]">
        <div className="relative">
          <div className="w-16 h-16 border-4 border-blue-500/20 rounded-full animate-ping absolute top-0 right-0"></div>
          <Loader2 className="animate-spin text-blue-500 relative z-10" size={64} strokeWidth={1.5} />
        </div>
        <p className="text-slate-400 mt-6 text-sm font-bold tracking-wider uppercase animate-pulse">جاري تحميل لوحة تحكم المشروع...</p>
      </div>
    );
  }

  if (!project) return null;

  const stat = statusMap[project.status] || statusMap['PLANNING'];
  const StatusIcon = stat.icon;

  // Calculators
  const totalBoqValue = project.boqItems?.reduce((acc: number, curr: any) => acc + (curr.quantity * curr.unitPrice), 0) || 0;
  const executedValue = project.boqItems?.reduce((acc: number, curr: any) => acc + (curr.executedQty * curr.unitPrice), 0) || 0;
  const progressPercent = totalBoqValue > 0 ? (executedValue / totalBoqValue) * 100 : 0;
  // Separate contracts calculation
  const subContractsValue = project.contracts
    ?.filter((c: any) => c.type !== 'MAIN_CONTRACT')
    .reduce((acc: number, curr: any) => acc + Number(curr.totalValue), 0) || 0;
    
  const mainContractsSum = project.contracts
    ?.filter((c: any) => c.type === 'MAIN_CONTRACT')
    .reduce((acc: number, curr: any) => acc + Number(curr.totalValue), 0) || 0;
    
  const mainContractValue = mainContractsSum > 0 ? mainContractsSum : (project.budget || totalBoqValue);
  // Real revenue = sum of certified invoice gross amounts
  const totalCertifiedRevenue = project.invoices
    ?.filter((inv: any) => inv.status === 'CERTIFIED')
    .reduce((acc: number, inv: any) => acc + Number(inv.grossAmount || 0), 0) || 0;

  // Real cost = sum of certified invoice net amounts + POs + Expenses
  const subcontractorCost = project.invoices
    ?.filter((inv: any) => inv.status === 'CERTIFIED')
    .reduce((acc: number, inv: any) => acc + Number(inv.netAmount || 0), 0) || 0;

  const poCost = project.purchaseOrders
    ?.filter((po: any) => po.status !== 'CANCELLED')
    .reduce((acc: number, po: any) => acc + Number(po.netAmount || po.totalAmount || 0), 0) || 0;

  const expensesCost = project.expenses
    ?.filter((exp: any) => exp.status !== 'REJECTED')
    .reduce((acc: number, exp: any) => acc + Number(exp.amount || 0), 0) || 0;

  const totalCertifiedCost = subcontractorCost + poCost + expensesCost;

  const certifiedInvoicesCount = project.invoices?.filter((inv: any) => inv.status === 'CERTIFIED').length || 0;

  return (
    <div className="space-y-8 w-full block animate-in fade-in zoom-in-95 duration-500 max-w-[1600px] mx-auto pb-12 relative">
      {/* Dynamic Glow Background */}
      <div className={`absolute top-0 right-1/4 w-[500px] h-[500px] bg-gradient-to-bl ${stat.glow} to-transparent rounded-full blur-[150px] pointer-events-none -z-10`} />

      {/* Hero Header */}
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6">
        <div className="flex items-center gap-5">
          <button onClick={() => router.push('/dashboard/projects')} className="flex items-center justify-center w-12 h-12 rounded-2xl bg-white/5 border border-white/10 hover:bg-white/10 hover:border-white/20 text-slate-300 hover:text-white transition-all shadow-lg hover:-translate-x-1" title="عودة للمشاريع">
            <ArrowRight size={22} />
          </button>
          <Link href={`/dashboard/projects/edit/${project.id}`} className="flex items-center justify-center w-12 h-12 rounded-2xl bg-white/5 border border-white/10 hover:bg-white/10 hover:border-amber-500/30 text-slate-300 hover:text-amber-400 transition-all shadow-lg hover:scale-105" title="تعديل بيانات المشروع">
            <Edit size={20} />
          </Link>
          <div className="flex-1">
            <div className="flex items-center gap-3 mb-2">
               <h1 className="text-4xl font-black text-white tracking-tight drop-shadow-sm line-clamp-1">
                 {project.name}
               </h1>
               <div className={`flex items-center gap-1.5 px-3 py-1 text-xs font-bold tracking-wider rounded-lg border ${stat.border} ${stat.bg} ${stat.color}`}>
                 <StatusIcon size={14} /> {stat.label}
               </div>
            </div>
            <div className="flex items-center gap-4 text-sm font-medium">
              <span className="text-slate-400 bg-slate-900/50 px-2.5 py-1 rounded-md border border-slate-800 font-mono uppercase tracking-widest text-[11px] shadow-inner">
                كود: {project.code}
              </span>
              <span className="flex items-center gap-1.5 text-slate-400">
                <Building2 size={14} className="text-blue-500" />
                {project.client?.name || "عميل النظام الداخلي"}
              </span>
            </div>
          </div>
        </div>
        
        <div className="flex items-center gap-3 w-full lg:w-auto">
          <Link href={`/dashboard/contracts/create?project=${project.id}`} className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-5 py-3 rounded-xl font-bold bg-white/5 hover:bg-white/10 border border-white/10 text-white transition-all shadow-lg text-sm">
            <FileSignature size={18} /> عقد جديد
          </Link>
          <Link href={`/dashboard/invoices/create?project=${project.id}`} className="flex-1 lg:flex-none flex items-center justify-center gap-2 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white font-bold py-3 px-6 rounded-xl transition-all shadow-lg hover:shadow-[0_0_20px_rgba(59,130,246,0.4)] hover:-translate-y-1 text-sm">
            <Wallet size={18} /> مستخلص جديد
          </Link>
        </div>
      </div>

      {/* Smart Tabs */}
      <div className="flex flex-wrap items-center gap-2 border-b border-white/10 pb-4">
        {[
          { id: 'OVERVIEW', label: 'اللوحة الرئيسية', icon: PieChart },
          { id: 'BOQ', label: 'بنود الأعمال (BOQ)', icon: ClipboardList, badge: project.boqItems?.length },
          { id: 'CONTRACTS', label: 'العقود (رئيسي / باطن)', icon: FileSignature, badge: project.contracts?.length },
          { id: 'DAFTRA', label: 'مزامنة دفترة (ERP)', icon: Activity, badge: 'Live' },
          { id: 'DPR', label: 'التقارير اليومية', icon: FileText, badge: project.dailyReports?.length || 0 },
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex items-center justify-center gap-2 px-5 py-2.5 rounded-xl text-sm font-bold transition-all relative ${
              activeTab === tab.id 
                ? tab.id === 'DAFTRA' ? 'text-white bg-emerald-500/10 border-emerald-500/30' : 'text-white bg-blue-500/10 border-blue-500/20' 
                : 'text-slate-400 hover:text-white hover:bg-white/5 border-transparent'
            } border flex-1 sm:flex-none whitespace-nowrap`}
          >
            <tab.icon size={18} className={activeTab === tab.id ? (tab.id === 'DAFTRA' ? 'text-emerald-400 animate-pulse' : 'text-blue-400') : ''} />
            {tab.label}
            {tab.badge !== undefined && (
              <span className={`px-2 py-0.5 rounded-md text-[10px] ml-1 uppercase tracking-wider ${
                activeTab === tab.id 
                  ? tab.id === 'DAFTRA' ? 'bg-emerald-500/20 text-emerald-300' : 'bg-blue-500/20 text-blue-300' 
                  : 'bg-slate-800 text-slate-500 font-mono'
              }`}>
                {tab.badge}
              </span>
            )}
          </button>
        ))}
      </div>

      <AnimatePresence mode="wait">
        <motion.div
           key={activeTab}
           initial={{ opacity: 0, y: 10 }}
           animate={{ opacity: 1, y: 0 }}
           exit={{ opacity: 0, y: -10 }}
           transition={{ duration: 0.2 }}
        >
          
          {/* OVERVIEW TAB */}
          {activeTab === 'OVERVIEW' && (
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              
              {/* Financial Progress Card */}
              <div className="lg:col-span-2 glass-dark border border-white/5 rounded-3xl p-8 relative overflow-hidden shadow-2xl flex flex-col justify-between">
                 <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-500/10 blur-[80px] rounded-full pointer-events-none" />
                 
                 <div className="relative z-10 flex justify-between items-start mb-10">
                   <div>
                     <h3 className="text-xl font-bold text-white mb-1 flex items-center gap-2">
                       <Wallet size={20} className="text-emerald-400" /> الحالة المالية والحصر للمشروع
                     </h3>
