              >
                <option value="" disabled>-- اختر جهة مالكة من دليل العملاء --</option>
                {clients.map(client => (
                  <option key={client.id} value={client.id}>
                    {client.name} {client.daftraClientId ? '🟢 (مربوط بدفترة)' : '🔴 (غير مربوط)'}
