          </div>
        </form>
      </motion.div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter, useParams } from "next/navigation";
import { motion } from "framer-motion";
import { Building2, Save, ArrowRight, Loader2 } from "lucide-react";
import axios from "axios";
import { API_BASE_URL } from "@/lib/api";

export default function EditProjectPage() {
  const router = useRouter();
  const params = useParams();
  const projectId = params.id as string;

  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState("");
  const [clients, setClients] = useState<any[]>([]);

  const [formData, setFormData] = useState({
    name: "",
    code: "",
    description: "",
    status: "PLANNING",
    clientId: "",
    startDate: "",
    endDate: ""
  });

  useEffect(() => {
    fetchData();
  }, [projectId]);

  const fetchData = async () => {
    try {
      const token = localStorage.getItem("token");
      const [clientsRes, projectRes] = await Promise.all([
        axios.get(`${API_BASE_URL}/v1/contacts/clients`, { headers: { Authorization: `Bearer ${token}` } }),
        axios.get(`${API_BASE_URL}/v1/projects/${projectId}`, { headers: { Authorization: `Bearer ${token}` } })
      ]);

      setClients(clientsRes.data);

      const prj = projectRes.data;
      setFormData({
        name: prj.name,
        code: prj.code,
        description: prj.description || "",
        status: prj.status,
        clientId: prj.clientId || "",
        startDate: prj.startDate ? new Date(prj.startDate).toISOString().split('T')[0] : "",
        endDate: prj.endDate ? new Date(prj.endDate).toISOString().split('T')[0] : ""
      });
    } catch (err) {
      setError("تعذر جلب بيانات المشروع");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError("");

    try {
      const token = localStorage.getItem("token");
      await axios.patch(
        `${API_BASE_URL}/v1/projects/${projectId}`,
        {
          ...formData,
          startDate: formData.startDate ? new Date(formData.startDate).toISOString() : undefined,
          endDate: formData.endDate ? new Date(formData.endDate).toISOString() : undefined,
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      router.push(`/dashboard/projects/${projectId}`);
    } catch (err: any) {
      setError(err.response?.data?.message || "حدث خطأ أثناء تحديث المشروع.");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh]">
         <Loader2 className="animate-spin text-blue-500 mb-4" size={48} />
         <p className="text-slate-400 font-bold">جاري تحميل بيانات المشروع...</p>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto space-y-6 w-full animate-in fade-in zoom-in-95 duration-500 pb-12">
      <div className="flex items-center gap-4">
        <button 
          onClick={() => router.back()}
          className="p-2.5 rounded-xl bg-white/5 hover:bg-white/10 text-slate-300 transition-colors"
        >
          <ArrowRight size={20} />
        </button>
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center gap-3">
            <Building2 className="text-blue-500" size={24} />
            تعديل بيانات المشروع
          </h1>
        </div>
      </div>

      <motion.div 
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="glass-dark border border-white/5 rounded-3xl p-6 sm:p-8"
      >
        <form onSubmit={handleSubmit} className="space-y-8">
          {error && (
            <div className="p-4 bg-rose-500/10 border border-rose-500/20 text-rose-400 rounded-xl text-sm">
              {error}
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-300">اسم المشروع</label>
              <input
                type="text"
                required
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
                className="w-full bg-slate-900/50 border border-slate-800 rounded-xl py-3 px-4 text-white focus:outline-none focus:ring-2 focus:ring-blue-500/50 transition-all"
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-300">كود المشروع</label>
              <input
                type="text"
                required
                value={formData.code}
                onChange={e => setFormData({...formData, code: e.target.value})}
                className="w-full bg-slate-900/50 border border-slate-800 rounded-xl py-3 px-4 text-white focus:outline-none focus:ring-2 focus:ring-blue-500/50 transition-all"
                dir="ltr"
              />
            </div>

            <div className="space-y-2 md:col-span-2">
              <label className="text-sm font-medium text-slate-300">الجهة المالكة</label>
              <select
                required
                value={formData.clientId}
                onChange={e => setFormData({...formData, clientId: e.target.value})}
                className="w-full bg-slate-900/50 border border-slate-800 rounded-xl py-3 px-4 text-white focus:outline-none focus:ring-2 focus:ring-blue-500/50 transition-all"
              >
                <option value="" disabled>-- اختر جهة مالكة --</option>
                {clients.map(client => (
                  <option key={client.id} value={client.id}>{client.name}</option>
                ))}
              </select>
            </div>

            <div className="space-y-2 md:col-span-2">
              <label className="text-sm font-medium text-slate-300">وصف نطاق العمل</label>
              <textarea
                value={formData.description}
                onChange={e => setFormData({...formData, description: e.target.value})}
                rows={3}
                className="w-full bg-slate-900/50 border border-slate-800 rounded-xl py-3 px-4 text-white focus:outline-none focus:ring-2 focus:ring-blue-500/50 transition-all"
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-300">تاريخ البداية</label>
              <input
                type="date"
                value={formData.startDate}
                onChange={e => setFormData({...formData, startDate: e.target.value})}
                className="w-full bg-slate-900/50 border border-slate-800 rounded-xl py-3 px-4 text-slate-300 focus:outline-none [color-scheme:dark]"
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-300">تاريخ التسليم</label>
              <input
                type="date"
                value={formData.endDate}
                onChange={e => setFormData({...formData, endDate: e.target.value})}
                className="w-full bg-slate-900/50 border border-slate-800 rounded-xl py-3 px-4 text-slate-300 focus:outline-none [color-scheme:dark]"
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-300">حالة المشروع</label>
              <select
                value={formData.status}
                onChange={e => setFormData({...formData, status: e.target.value})}
                className="w-full bg-slate-900/50 border border-slate-800 rounded-xl py-3 px-4 text-white focus:outline-none focus:ring-2 focus:ring-blue-500/50 transition-all"
              >
                <option value="PLANNING">قيد التخطيط والدراسة</option>
                <option value="ACTIVE">نشط وقيد التنفيذ</option>
                <option value="COMPLETED">مكتمل</option>
                <option value="ON_HOLD">متوقف</option>
              </select>
            </div>
          </div>

          <div className="pt-6 border-t border-white/5 flex gap-4 justify-end">
            <button
              type="button"
              onClick={() => router.back()}
              className="px-6 py-2.5 rounded-xl font-medium text-slate-300 hover:bg-white/5 transition-colors"
            >
              إلغاء
            </button>
            <button
              type="submit"
              disabled={isSubmitting}
              className="flex items-center gap-2 px-8 py-2.5 rounded-xl font-medium bg-blue-600 hover:bg-blue-500 text-white shadow-[0_0_15px_rgba(59,130,246,0.3)] transition-all disabled:opacity-50"
            >
              {isSubmitting ? <Loader2 size={18} className="animate-spin" /> : <Save size={18} />}
              <span>حفظ التعديلات</span>
            </button>
          </div>
        </form>
      </motion.div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { motion, AnimatePresence } from "framer-motion";
import { 
  Building2, 
  Search, 
  Plus, 
  MoreVertical,
  Calendar,
  User,
  Activity,
  ArrowUpRight,
  Filter,
  CheckCircle2,
  Clock,
  HardHat,
  Wallet,
  Trash2
} from "lucide-react";
import axios from "axios";
import { useRouter } from "next/navigation";
import { API_BASE_URL } from "@/lib/api";

export default function ProjectsPage() {
  const router = useRouter();
  const [projects, setProjects] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [activeFilter, setActiveFilter] = useState("ALL");
  const [userRole, setUserRole] = useState("");

  useEffect(() => {
    const userStr = localStorage.getItem("user");
    if (userStr) {
      try {
        const u = JSON.parse(userStr);
        setUserRole(u.role || "");
      } catch (e) {}
    }
    fetchProjects();
  }, []);

  const fetchProjects = async () => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get(`${API_BASE_URL}/v1/projects`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProjects(res.data);
    } catch (err) {
      console.error("Failed to fetch projects");
    } finally {
      setIsLoading(false);
    }
  };

  const deleteProject = async (e: any, id: string) => {
    e.stopPropagation();
    if (!confirm("هل أنت متأكد من رغبتك في حذف هذا المشروع نهائياً؟ هذا الإجراء لا يمكن التراجع عنه.")) return;
    
    try {
      const token = localStorage.getItem("token");
      await axios.delete(`${API_BASE_URL}/v1/projects/${id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      fetchProjects();
    } catch (err: any) {
      alert(err.response?.data?.message || "فشل حذف المشروع");
    }
  };

  const statusMap: Record<string, { label: string, color: string, border: string, bg: string, glow: string, icon: any }> = {
    PLANNING: { label: "قيد التخطيط", color: "text-amber-400", border: "border-amber-500/30", bg: "bg-amber-500/10", glow: "from-amber-500/20 to-transparent", icon: Clock },
    ACTIVE: { label: "نشط (قيد التنفيذ)", color: "text-blue-400", border: "border-blue-500/30", bg: "bg-blue-500/10", glow: "from-blue-500/20 to-transparent", icon: HardHat },
    COMPLETED: { label: "مكتمل", color: "text-emerald-400", border: "border-emerald-500/30", bg: "bg-emerald-500/10", glow: "from-emerald-500/20 to-transparent", icon: CheckCircle2 },
    ON_HOLD: { label: "متوقف", color: "text-rose-400", border: "border-rose-500/30", bg: "bg-rose-500/10", glow: "from-rose-500/20 to-transparent", icon: Activity },
  };

  const filters = [
    { id: "ALL", label: "جميع المشاريع", count: projects.length },
    { id: "ACTIVE", label: "نشطة", count: projects.filter(p => p.status === 'ACTIVE').length },
    { id: "PLANNING", label: "قيد التخطيط", count: projects.filter(p => p.status === 'PLANNING').length },
    { id: "COMPLETED", label: "مكتملة", count: projects.filter(p => p.status === 'COMPLETED').length },
  ];

  const filteredProjects = projects.filter(p => {
    const matchesSearch = p.name.includes(search) || p.code.includes(search);
    const matchesStatus = activeFilter === "ALL" || p.status === activeFilter;
    return matchesSearch && matchesStatus;
  });

  return (
    <div className="space-y-8 w-full block animate-in fade-in zoom-in-95 duration-500 max-w-[1600px] mx-auto pb-12 relative">
      {/* Absolute Header Glow */}
      <div className="absolute top-0 right-1/4 w-[400px] h-[400px] bg-blue-600/10 rounded-full blur-[150px] pointer-events-none -z-10" />

      {/* Header Area */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-6">
        <div className="flex items-center gap-5">
          <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-blue-500/20 to-indigo-500/10 flex items-center justify-center border border-blue-500/20 shadow-lg">
            <Building2 className="text-blue-400" size={28} />
          </div>
          <div>
            <h1 className="text-3xl font-extrabold text-white flex flex-wrap items-center gap-3 drop-shadow-sm">
              إدارة المشاريع
            </h1>
            <div className="text-slate-400 text-sm mt-1.5 font-medium flex items-start sm:items-center gap-2">
              <Activity size={14} className="text-blue-500 shrink-0 mt-0.5 sm:mt-0" />
              <span className="leading-relaxed">أضف، تتبع، ووّزع ميزانيات المشاريع، وراقب خطة التنفيذ خطوة بخطوة.</span>
            </div>
          </div>
        </div>
        
        {userRole !== "Viewer" && (
          <Link
            href="/dashboard/projects/create" 
            className="flex items-center gap-2 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white font-bold py-3 px-6 rounded-xl transition-all shadow-[0_0_20px_rgba(59,130,246,0.3)] hover:shadow-[0_0_30px_rgba(59,130,246,0.5)] group hover:-translate-y-1"
          >
            <Plus size={20} className="group-hover:rotate-90 transition-transform" />
            <span>إضافة مشروع جديد</span>
          </Link>
        )}
      </div>

      {/* Filters and Search Toolbar */}
      <div className="glass-dark border border-white/5 p-2 rounded-2xl flex flex-col lg:flex-row items-center justify-between gap-4 bg-slate-900/60 backdrop-blur-md shadow-2xl">
        {/* Dynamic Filters */}
        <div className="flex flex-wrap items-center gap-2 w-full lg:w-auto p-1 bg-slate-900/50 rounded-xl">
          {filters.map(filter => (
            <button
              key={filter.id}
              onClick={() => setActiveFilter(filter.id)}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-bold transition-all whitespace-nowrap ${
                activeFilter === filter.id 
                ? 'bg-blue-600 text-white shadow-lg'
                : 'text-slate-400 hover:bg-white/5 hover:text-slate-200'
              }`}
            >
              {filter.label}
              <span className={`px-2 py-0.5 rounded-md text-[10px] ${activeFilter === filter.id ? 'bg-white/20' : 'bg-slate-800'}`}>
                {filter.count}
              </span>
            </button>
          ))}
        </div>

        {/* Global Search */}
        <div className="relative w-full lg:w-96 group px-2 lg:px-0">
          <Search className="absolute right-4 lg:right-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-400 transition-colors" size={18} />
          <input
            type="text"
            placeholder="ابحث برمز المشروع أو الكود..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full bg-slate-950/50 border border-slate-700/80 rounded-xl py-3 pr-12 pl-4 text-white text-sm placeholder-slate-500 focus:outline-none focus:border-blue-500/50 focus:ring-1 focus:ring-blue-500/50 transition-all shadow-inner group-hover:border-slate-600"
          />
        </div>
      </div>

      {/* Projects Grid */}
      {isLoading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {[1,2,3,4,5,6].map(i => (
            <div key={i} className="h-64 bg-slate-800/20 rounded-3xl border border-white/5 animate-pulse relative overflow-hidden">
               <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/[0.02] to-transparent translate-x-[-100%] animate-[shimmer_2s_infinite]" />
            </div>
          ))}
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          <AnimatePresence>
            {filteredProjects.length === 0 ? (
              <motion.div 
                initial={{ opacity: 0 }} animate={{ opacity: 1 }}
                className="col-span-full py-20 flex flex-col items-center justify-center text-center glass-dark rounded-3xl border border-white/5 shadow-2xl"
              >
                <Filter size={48} className="text-slate-600 mb-4" />
                <h3 className="text-xl font-bold text-white mb-2">لم يجد النظام أي مشاريع</h3>
                <p className="text-slate-400">جرب البحث بكلمات مختلفة أو قم بتغيير فلاتر التصنيف الحالية.</p>
              </motion.div>
            ) : (
              filteredProjects.map((project, i) => {
                const stat = statusMap[project.status] || statusMap['PLANNING'];
                const StatusIcon = stat.icon;

                return (
                  <motion.div
                    layout
                    initial={{ opacity: 0, scale: 0.95, y: 20 }}
                    animate={{ opacity: 1, scale: 1, y: 0 }}
                    exit={{ opacity: 0, scale: 0.95 }}
                    transition={{ delay: i * 0.05 }}
                    key={project.id}
                    onClick={() => router.push(`/dashboard/projects/${project.id}`)}
                    className="rounded-3xl glass-dark border border-white/10 hover:border-blue-500/30 transition-all duration-300 group overflow-hidden relative flex flex-col cursor-pointer shadow-xl hover:shadow-[0_10px_40px_rgba(59,130,246,0.1)] hover:-translate-y-1"
                  >
                    {/* Glowing Accent */}
                    <div className={`absolute -top-24 -right-24 w-48 h-48 bg-gradient-to-br ${stat.glow} rounded-full blur-3xl opacity-40 group-hover:opacity-100 transition-opacity`} />
                    <div className={`absolute top-0 inset-x-0 h-1 bg-gradient-to-r ${stat.glow} opacity-60`} />

                    <div className="p-6 relative z-10 flex-1 flex flex-col">
                      <div className="flex justify-between items-start mb-5">
                        <div className={`flex items-center gap-1.5 px-3 py-1.5 text-[11px] font-bold tracking-wider rounded-lg border ${stat.border} ${stat.bg} ${stat.color} shadow-sm`}>
                          <StatusIcon size={14} />
                          {stat.label}
                        </div>
                        {userRole !== "Viewer" && (
                          <div className="flex items-center gap-1">
                            <button 
                              className="text-slate-500 hover:text-white transition-colors p-1.5 rounded-lg hover:bg-white/10" 
                              onClick={(e) => { e.stopPropagation(); /* specific action */ }}
                              title="خيارات إضافية"
                            >
                              <MoreVertical size={16} />
                            </button>
                            <button 
                              className="text-rose-500/70 hover:text-rose-400 transition-colors p-1.5 rounded-lg hover:bg-rose-500/10" 
                              onClick={(e) => deleteProject(e, project.id)}
                              title="حذف المشروع"
                            >
                              <Trash2 size={16} />
                            </button>
                          </div>
                        )}
                      </div>

                      <div className="mb-6">
                        <h3 className="text-xl font-extrabold text-white mb-2 line-clamp-1 group-hover:text-blue-400 transition-colors drop-shadow-sm">{project.name}</h3>
                        <div className="inline-flex items-center gap-2 px-2.5 py-1 rounded-md bg-slate-900/80 border border-slate-700/50 shadow-inner">
                          <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">كود المشروع</span>
                          <span className="text-xs font-mono font-bold text-slate-300">{project.code}</span>
                        </div>
                      </div>

                      <div className="space-y-3.5 mb-2 mt-auto">
                        <div className="flex items-center gap-3 text-sm text-slate-300 bg-white/[0.02] p-2 rounded-xl border border-white/5 border-transparent group-hover:border-white/5 transition-all">
                          <User size={16} className="text-slate-500 shrink-0" />
                          <span className="truncate">{project.manager ? `${project.manager.firstName} ${project.manager.lastName}` : "مدير غير محدد"}</span>
                        </div>
                        <div className="flex items-center gap-3 text-sm text-slate-300 bg-white/[0.02] p-2 rounded-xl border border-white/5 border-transparent group-hover:border-white/5 transition-all">
                          <Wallet size={16} className="text-slate-500 shrink-0" />
                          <span className="font-mono text-emerald-400 font-medium">
                            {(() => {
                              const mainContractsSum = project.contracts?.reduce((acc: number, c: any) => acc + Number(c.totalValue), 0) || 0;
                              const displayBudget = project.budget || mainContractsSum;
                              return displayBudget > 0 ? `SAR ${Number(displayBudget).toLocaleString()}` : "الميزانية غير محددة";
                            })()}
                          </span>
                        </div>
                        <div className="flex items-center gap-3 text-sm text-slate-300 bg-white/[0.02] p-2 rounded-xl border border-white/5 border-transparent group-hover:border-white/5 transition-all">
                          <Calendar size={16} className="text-slate-500 shrink-0" />
                          <span className="font-mono">{project.startDate ? new Date(project.startDate).toLocaleDateString("ar-SA") : "غير محدد"}</span>
                        </div>
                      </div>
                    </div>

                    {/* Card Footer */}
                    <div className="border-t border-white/5 p-4 bg-slate-900/40 backdrop-blur-md flex items-center justify-between group-hover:bg-slate-900/60 transition-colors">
                      <div className="flex items-center gap-2 text-xs text-slate-400 font-semibold uppercase tracking-wider">
                        عرض لوحة قيادة المشروع
                      </div>
                      <div className={`w-8 h-8 rounded-full flex items-center justify-center transition-all duration-300 shadow-md ${stat.bg} ${stat.color} group-hover:scale-110 group-hover:rotate-12`}>
                        <ArrowUpRight size={18} />
                      </div>
                    </div>
                  </motion.div>
                );
              })
            )}
          </AnimatePresence>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { API_BASE_URL } from "@/lib/api";
import { useRouter, useParams } from "next/navigation";
import { Loader2, ArrowRight, Printer, CheckCircle2, Clock, Package, RefreshCcw, FileSpreadsheet } from "lucide-react";
import axios from "axios";
import { exportToCsv } from "@/lib/exportUtils";
import { useDownloadPdf } from "@/hooks/useDownloadPdf";
import PrintHeader from "../../components/PrintHeader";
import PrintFooter from "../../components/PrintFooter";
import PrintLetterhead from "../../components/PrintLetterhead";

export default function ViewPurchaseOrderPage() {
  const router = useRouter();
  const params = useParams();
  const orderId = params.id as string;
  
  const [order, setOrder] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const { pdfRef, downloadPdf } = useDownloadPdf();

  useEffect(() => {
    if (orderId) fetchOrder();
  }, [orderId]);

  const fetchOrder = async () => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get(`${API_BASE_URL}/v1/purchases/${orderId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setOrder(res.data);
    } catch (err) {
      alert("تعذر جلب بيانات أمر الشراء");
      router.back();
    } finally {
      setIsLoading(false);
    }
  };

  const handleSyncFromDaftra = async () => {
    if (!order.daftraId) {
      alert('أمر الشراء هذا غير مربوط بدفترة بعد.');
      return;
    }
    setIsSyncing(true);
    try {
      const token = localStorage.getItem('token');
      await axios.patch(`${API_BASE_URL}/v1/purchases/${orderId}/sync-daftra`, {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      alert('تم التحقق من دفترة - أمر الشراء موجود ومتزامن.');
      await fetchOrder();
    } catch (err: any) {
      const msg = err.response?.data?.message || err.message || 'خطأ مجهول';
      alert(msg);
      // إعادة تحميل الصفحة لعرض الحالة الجديدة (PENDING) إذا تم الحذف من دفترة
      await fetchOrder();
    } finally {
      setIsSyncing(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const handleExportExcel = () => {
    if (!order?.items) return;
    const exportData = order.items.map((item: any, i: number) => ({
      "م": i + 1,
      "الصنف / الوصف": item.material?.name || 'مادة بدون اسم',
      "الكمية": item.quantity,
      "السعر الإفرادي": item.unitPrice,
      "الإجمالي": item.totalPrice
    }));
    exportToCsv(`PO_${order.poNumber}.csv`, exportData);
  };

  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] print:hidden">
         <Loader2 className="animate-spin text-indigo-500 mb-4" size={48} />
         <p className="text-slate-400 font-bold">جاري تحميل أمر الشراء...</p>
      </div>
    );
  }

  if (!order) return null;

  return (
    <>
      {/* Screen View */}
      <div className="max-w-5xl mx-auto space-y-6 w-full animate-in fade-in zoom-in-95 duration-500 pb-12 print:hidden relative">
        <div className="flex items-center justify-between bg-slate-900/50 p-6 rounded-3xl border border-white/5 shadow-lg">
          <div className="flex items-center gap-4">
            <button onClick={() => router.back()} className="p-3 bg-slate-800 hover:bg-slate-700 text-white rounded-2xl transition">
              <ArrowRight size={20} />
            </button>
            <div>
              <h1 className="text-2xl font-black text-white flex items-center gap-3">
                أمر شراء (PO) #{order.poNumber}
              </h1>
              <p className="text-slate-400 mt-1 font-bold tracking-wider">المشروع: {order.project?.name || 'تخزين عام (بدون مشروع)'}</p>
            </div>
          </div>
          <div className="flex items-center gap-3">
            {order.status === 'APPROVED' && order.daftraId && (
              <button
                onClick={handleSyncFromDaftra}
                disabled={isSyncing}
                className="flex items-center gap-2 px-5 py-3 bg-blue-600/20 hover:bg-blue-600 text-blue-400 hover:text-white rounded-xl font-bold border border-blue-500/30 transition disabled:opacity-50"
              >
                <RefreshCcw size={18} className={isSyncing ? 'animate-spin' : 'group-hover:rotate-180'} />
                {isSyncing ? 'جاري التحقق...' : 'تحديث من دفترة'}
              </button>
            )}
            <button onClick={handleExportExcel} className="flex items-center gap-2 px-5 py-3 bg-emerald-600/20 hover:bg-emerald-600 text-emerald-400 hover:text-white rounded-xl font-bold border border-emerald-500/30 transition shadow-lg text-sm">
               <FileSpreadsheet size={18} /> Excel
            </button>
            <button onClick={() => downloadPdf(`PO_${order?.poNumber || 'draft'}.pdf`)} className="flex items-center gap-2 px-6 py-3 bg-rose-600 hover:bg-rose-500 text-white rounded-xl font-bold shadow-lg transition hover:-translate-y-1">
              <Printer size={18} /> PDF
            </button>
            <button onClick={handlePrint} className="flex items-center gap-2 px-6 py-3 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl font-bold shadow-[0_0_20px_rgba(79,70,229,0.3)] hover:shadow-[0_0_30px_rgba(79,70,229,0.5)] transition hover:-translate-y-1">
              <Printer size={18} /> معاينة وطباعة رسمية
            </button>
          </div>
        </div>

        <div className="glass-dark border border-white/5 p-12 rounded-3xl text-center shadow-2xl relative overflow-hidden">
           <div className="absolute top-0 right-1/2 translate-x-1/2 w-64 h-64 bg-indigo-500/10 blur-[100px] rounded-full pointer-events-none" />
           <p className="text-8xl mb-6">🖨️</p>
           <h2 className="text-3xl font-black text-white mb-4">نموذج أمر الشراء جاهز للطباعة</h2>
           <p className="text-slate-400 max-w-lg mx-auto text-lg leading-relaxed">
             اضغط على زر (الطباعة الرسمية) بالأعلى لمعاينة النموذج الورقي المعتمد بشكله الاحترافي والأنيق مع التوقيعات الدفترية.
           </p>
        </div>
      </div>

      {/* PRINT VIEW */}
      <div ref={pdfRef} className="hidden print:block print-on-letterhead print:!text-black font-sans" dir="rtl">
        {/* ===== الورقة الرسمية كخلفية ===== */}
        <PrintLetterhead />

        {/* ===== رأس الورقة باسم الشركة ===== */}
        <PrintHeader />

        {/* ===== البيانات فوق الورقة ===== */}
        <div className="mb-8">
          <div className="inline-block bg-slate-50 p-3 rounded-lg border border-slate-200 text-right">
            <p className="text-sm font-bold text-slate-800">رقم الأمر (PO No): <span className="font-mono text-rose-700">#{order.poNumber}</span></p>
            <p className="text-sm font-bold text-slate-800 mt-1">تاريخ الإصدار (Date): <span className="font-mono">{new Date(order.issueDate).toLocaleDateString('en-GB')}</span></p>
          </div>
          <h1 className="text-3xl font-black text-slate-900 mt-3">أمر شراء — Purchase Order</h1>
        </div>

        <div className="grid grid-cols-2 gap-8 mb-10 text-sm break-inside-avoid">
           <div className="bg-white p-4 border-2 border-slate-200 rounded-lg shadow-sm">
              <p className="text-slate-500 font-black mb-3 uppercase text-xs tracking-wider border-b border-slate-100 pb-2">عناية المورد (Supplier Details)</p>
              <p className="mb-2"><span className="font-bold w-28 inline-block text-slate-600">السادة / شركة:</span> <span className="font-black text-lg text-slate-900">{order.supplier?.name}</span></p>
              <p className="mb-2"><span className="font-bold w-28 inline-block text-slate-600">الرقم الضريبي:</span> <span className="font-mono font-bold text-slate-900">{order.supplier?.taxNumber || '-'}</span></p>
              <p className="mb-2"><span className="font-bold w-28 inline-block text-slate-600">رقم التواصل:</span> <span className="font-mono font-bold text-slate-900">{order.supplier?.phone || '-'}</span></p>
           </div>
           
           <div className="bg-white p-4 border-2 border-slate-200 rounded-lg shadow-sm">
              <p className="text-slate-500 font-black mb-3 uppercase text-xs tracking-wider border-b border-slate-100 pb-2">معلومات التوصيل (Delivery Details)</p>
              <p className="mb-2"><span className="font-bold w-28 inline-block text-slate-600">الموقع/المشروع:</span> <span className="font-black text-lg text-slate-900">{order.project?.name || 'مستودع الشركة العام'}</span></p>
              {order.project?.code && <p className="mb-2"><span className="font-bold w-28 inline-block text-slate-600">رمز المشروع:</span> <span className="font-mono font-bold text-slate-900">{order.project.code}</span></p>}
              <p className="mb-2"><span className="font-bold w-28 inline-block text-slate-600">تاريخ التوريد:</span> <span className="font-mono font-bold text-slate-900">{order.expectedDate ? new Date(order.expectedDate).toLocaleDateString('en-GB') : 'ASAP (في أقرب وقت)'}</span></p>
           </div>
        </div>

        <h3 className="font-black text-slate-900 mb-3 px-2 text-lg">قـائمة المـواد المطلوبة (Items List):</h3>
        <table className="w-full text-right text-sm border-collapse mb-10">
          <thead>
            <tr className="bg-slate-200 border-2 border-slate-900 text-slate-900 text-xs font-black uppercase">
              <th className="p-3 border-2 border-slate-900 text-center w-12">م</th>
              <th className="p-3 border-2 border-slate-900">الصنف / الوصف الدقيق</th>
              <th className="p-3 border-2 border-slate-900 text-center w-20">الكمية</th>
              <th className="p-3 border-2 border-slate-900 text-center w-28">السعر الإفرادي</th>
              <th className="p-3 border-2 border-slate-900 text-center w-32">الإجمالي (SAR)</th>
            </tr>
          </thead>
          <tbody>
            {order.items?.map((item: any, i: number) => (
               <tr key={item.id} className="border border-slate-300">
                 <td className="p-2 border border-slate-900 text-center font-bold text-slate-600">{i + 1}</td>
                 <td className="p-2 border border-slate-900 font-bold text-slate-900 text-base">{item.material?.name || 'مادة بدون اسم'}</td>
                 <td className="p-2 border border-slate-900 text-center font-mono font-black text-slate-900 text-base">{item.quantity}</td>
                 <td className="p-2 border border-slate-900 text-center font-mono text-slate-800">{Number(item.unitPrice).toLocaleString()}</td>
                 <td className="p-2 border border-slate-900 text-center font-mono font-black text-slate-900 bg-slate-50">{Number(item.totalPrice).toLocaleString()}</td>
               </tr>
            ))}
          </tbody>
        </table>

        <div className="flex justify-end mb-16 break-inside-avoid">
          <div className="w-1/2 border-2 border-slate-900 rounded-lg overflow-hidden shadow-md">
            <table className="w-full text-right border-collapse text-sm">
              <tbody>
                <tr className="border-b border-slate-200">
                   <td className="p-4 font-bold bg-slate-50 text-slate-700">المجموع الفرعي (Subtotal):</td>
                   <td className="p-4 font-mono font-black text-left text-slate-900">{Number(order.totalAmount).toLocaleString(undefined, {minimumFractionDigits: 2})}</td>
                </tr>
                {Number(order.taxAmount) > 0 && (
                  <tr className="border-b border-slate-200">
                     <td className="p-4 font-bold bg-slate-50 text-slate-700">ضريبة القيمة المضافة (VAT 15%):</td>
                     <td className="p-4 font-mono font-black text-left text-slate-900">{Number(order.taxAmount).toLocaleString(undefined, {minimumFractionDigits: 2})}</td>
                  </tr>
                )}
                <tr className="bg-slate-900 text-white">
                   <td className="p-5 font-black uppercase tracking-widest text-lg">الصافي المعتمد (Net Total):</td>
                   <td className="p-5 font-mono font-black text-left text-2xl">SAR {Number(order.netAmount).toLocaleString(undefined, {minimumFractionDigits: 2})}</td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>

        <div className="mt-16 pt-8 break-inside-avoid border-t-2 border-slate-100 text-black">
          <h3 className="font-black text-lg mb-10 border-b-2 border-slate-800 pb-2 w-max text-slate-800 uppercase tracking-widest">الاعتمادات والموافقات (Approvals):</h3>
          <div className="grid grid-cols-3 gap-8 text-center text-sm">
            <div className="flex flex-col items-center">
              <p className="font-bold text-slate-800 mb-4 uppercase tracking-widest text-xs">مُعِد الطلب / المشتريات (Procurement)</p>
              <div className="border-2 border-slate-200 bg-slate-50 text-slate-700 p-2 rounded-xl inline-block text-center shadow-sm w-48 relative overflow-hidden">
                <div className="absolute inset-0 bg-slate-100 opacity-50"></div>
                <p className="text-[10px] font-bold uppercase tracking-widest mb-1 border-b border-slate-200 pb-1 relative z-10">مُسجل إلكترونياً (E-Prepared)</p>
                <p className="text-xs font-black mt-1 relative z-10">{order.createdBy || (typeof window !== 'undefined' ? JSON.parse(localStorage.getItem('user') || '{}').name : '') || 'مسؤول المشتريات'}</p>
                <p className="text-[9px] font-mono mt-1 relative z-10">{new Date(order.createdAt).toLocaleDateString('en-GB')}</p>
              </div>
            </div>
            <div className="flex flex-col items-center">
              <p className="font-bold text-slate-800 mb-16 uppercase tracking-widest text-xs">المدير المالي (Finance Manager)</p>
              <p className="text-slate-400 w-full border-b-2 border-dashed border-slate-400 mt-auto"></p>
            </div>
            <div className="flex flex-col items-center">
               <p className="font-bold text-slate-800 mb-4 uppercase tracking-widest text-xs">الاعتماد النهائي (General Manager)</p>
               {order.status === 'APPROVED' ? (
                 <div className="border-2 border-emerald-500 bg-emerald-50 text-emerald-800 p-2 rounded-xl inline-block text-center shadow-md w-56 relative overflow-hidden transform -rotate-2 mt-2">
                   <div className="absolute inset-0 bg-emerald-500 opacity-5"></div>
                   <p className="text-[10px] font-black uppercase tracking-widest mb-1 border-b border-emerald-200 pb-1 relative z-10 text-emerald-600">مُعتمد إلكترونياً (E-Approved)</p>
                   <p className="text-sm font-black mt-1 relative z-10">{order.approvedBy || (typeof window !== 'undefined' ? JSON.parse(localStorage.getItem('user') || '{}').name : '') || 'المدير العام'}</p>
                   <p className="text-[9px] font-mono mt-1 relative z-10">{order.approvedAt ? new Date(order.approvedAt).toLocaleString('en-GB') : new Date(order.updatedAt).toLocaleString('en-GB')}</p>
                 </div>
               ) : (
                 <p className="text-slate-400 w-full border-b-2 border-dashed border-slate-400 mt-auto"></p>
               )}
            </div>
          </div>
        </div>
        
        {/* Print Footer — الورقة الرسمية */}
        <div className="fixed bottom-0 left-0 w-full bg-white px-8 pb-2">
          <PrintFooter />
        </div>
      </div>
    </>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { motion } from "framer-motion";
import { 
  ShoppingCart, 
  Save, 
  ArrowRight, 
  Loader2, 
  PlusCircle,
  Trash2,
  Package,
  Building2,
  Calendar,
  User,
  CheckCircle2,
  Receipt
} from "lucide-react";
import axios from "axios";
import { API_BASE_URL } from "@/lib/api";

export default function CreatePurchasePage() {
  const router = useRouter();
  const [isLoading, setIsLoading] = useState(false);
  const [projects, setProjects] = useState<any[]>([]);
  const [suppliers, setSuppliers] = useState<any[]>([]);
  
  const [formData, setFormData] = useState({
    projectId: "",
    supplierName: "",
    expectedDate: "",
    hasVat: true,
    items: [{ materialName: "", unit: "حبه", qty: 1, price: 0 }]
  });

  useEffect(() => {
    fetchProjects();
    fetchSuppliers();
  }, []);

  const fetchProjects = async () => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get(`${API_BASE_URL}/v1/projects`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProjects(res.data);
      if (res.data.length > 0) {
        setFormData(prev => ({ ...prev, projectId: res.data[0].id }));
      }
    } catch (err) {}
  };

  const fetchSuppliers = async () => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get(`${API_BASE_URL}/v1/integration/daftra/pms-suppliers`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setSuppliers(res.data);
    } catch (err) {}
  };

  const calculateTotal = () => {
    return formData.items.reduce((sum, item) => sum + (item.qty * item.price), 0);
  };

  const handleAddItem = () => {
    setFormData({
      ...formData,
      items: [...formData.items, { materialName: "", unit: "حبه", qty: 1, price: 0 }]
    });
  };

  const handleRemoveItem = (index: number) => {
    const newItems = formData.items.filter((_, i) => i !== index);
    setFormData({ ...formData, items: newItems });
  };

  const handleItemChange = (index: number, field: string, value: any) => {
    const newItems = [...formData.items];
    newItems[index] = { ...newItems[index], [field]: value };
    setFormData({ ...formData, items: newItems });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const token = localStorage.getItem("token");
      await axios.post(
        `${API_BASE_URL}/v1/purchases`,
        {
          ...formData,
          expectedDate: formData.expectedDate ? new Date(formData.expectedDate).toISOString() : undefined,
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      router.push("/dashboard/purchases");
    } catch (err: any) {
      alert("حدث خطأ أثناء رفع أمر الشراء.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-6xl mx-auto space-y-8 w-full animate-in fade-in zoom-in-95 duration-500 pb-12 relative">
      {/* Background glow */}
      <div className="absolute top-0 right-1/4 w-[500px] h-[500px] bg-indigo-600/10 rounded-full blur-[120px] pointer-events-none -z-10" />

      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-6">
        <div className="flex items-center gap-5">
          <button onClick={() => router.back()} className="flex items-center justify-center w-12 h-12 rounded-2xl bg-white/5 border border-white/10 hover:bg-white/10 hover:border-white/20 text-slate-300 hover:text-white transition-all shadow-lg hover:-translate-x-1">
            <ArrowRight size={22} />
          </button>
          <div>
            <h1 className="text-3xl font-black text-white tracking-tight flex items-center gap-3 drop-shadow-sm">
              <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-indigo-500/20 to-blue-500/10 flex items-center justify-center border border-indigo-500/20 shadow-lg">
                <ShoppingCart className="text-indigo-400" size={24} />
              </div>
              إنشاء طلب شراء (PO)
            </h1>
            <p className="text-slate-400 text-sm mt-2 font-medium">إنشاء أمر استعاضة أو شراء مواد للمشروع وربطها بالمورد.</p>
          </div>
        </div>
      </div>

      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="glass-dark border border-white/5 rounded-3xl p-6 sm:p-8">
        <form onSubmit={handleSubmit} className="space-y-8">
          
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="space-y-3">
              <label className="text-sm font-bold text-slate-300 flex items-center gap-2">
                <Building2 size={16} className="text-indigo-400" />
                المشروع المستهدف بالمورد
              </label>
              <div className="relative">
                <select
                  required
                  value={formData.projectId}
                  onChange={e => setFormData({...formData, projectId: e.target.value})}
                  className="w-full bg-slate-950/50 border border-white/10 hover:border-indigo-500/30 rounded-xl py-3.5 px-4 text-white font-medium focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all appearance-none cursor-pointer shadow-inner"
                >
                  <option value="" disabled className="bg-slate-900">-- اختر المشروع --</option>
                  {projects.map(p => <option key={p.id} value={p.id} className="bg-slate-900">{p.name}</option>)}
                </select>
                <div className="absolute left-4 top-1/2 -translate-y-1/2 pointer-events-none text-slate-500">▼</div>
              </div>
            </div>

            <div className="space-y-3 md:col-span-2">
              <label className="text-sm font-bold text-indigo-300 flex items-center gap-2">
                <User size={16} className="text-indigo-400" />
                المورد المعتمد / المحتمل (Supplier)
              </label>
              <input 
                type="text" 
                list="suppliersDropdown"
                required 
                value={formData.supplierName} 
                onChange={e => setFormData({...formData, supplierName: e.target.value})} 
                className="w-full bg-indigo-500/5 hover:bg-indigo-500/10 border border-indigo-500/20 hover:border-indigo-500/40 rounded-xl py-3.5 px-4 text-white font-medium placeholder-indigo-300/30 focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all shadow-inner" 
                placeholder="اختر أو اكتب اسم المورد..." 
                autoComplete="off"
              />
              <datalist id="suppliersDropdown">
                {suppliers.map(s => <option key={s.id} value={s.name}>{s.daftraSupplierId ? '✅ مربوط بدفترة' : ''}</option>)}
              </datalist>
            </div>

            <div className="space-y-3 md:col-span-3 lg:col-span-1">
              <label className="text-sm font-bold text-slate-300 flex items-center gap-2">
                <Calendar size={16} className="text-indigo-400" />
                تاريخ التوريد المتوقع بالموقع
              </label>
              <input type="date" required value={formData.expectedDate} onChange={e => setFormData({...formData, expectedDate: e.target.value})} className="w-full bg-slate-950/50 border border-white/10 hover:border-indigo-500/30 rounded-xl py-3.5 px-4 text-slate-200 font-medium focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all shadow-inner" style={{ colorScheme: 'dark' }} />
            </div>
          </div>

          <div className="border border-white/5 rounded-3xl overflow-hidden bg-gradient-to-b from-slate-900/50 to-slate-950/50 w-full p-6 shadow-xl relative">
            <div className="absolute top-0 right-0 w-full h-[1px] bg-gradient-to-r from-transparent via-indigo-500/20 to-transparent" />
            <div className="flex items-center justify-between mb-6">
              <h3 className="font-black text-xl text-white flex items-center gap-2 drop-shadow-sm">
                <Package className="text-indigo-400" size={24} />
                قائمة المواد المطلوبة
              </h3>
              <button type="button" onClick={handleAddItem} className="flex items-center gap-2 text-sm font-bold text-white bg-indigo-500/20 hover:bg-indigo-500/30 border border-indigo-500/30 px-4 py-2 rounded-xl transition-all shadow-lg hover:shadow-indigo-500/20">
                <PlusCircle size={18} /> إضافة مادة
              </button>
            </div>

            <div className="space-y-3">
              {/* Header Row for large screens */}
              <div className="hidden md:flex items-center gap-3 px-3 py-2 text-slate-400 font-bold text-xs uppercase tracking-wider mb-2">
                <div className="flex-1">بيان وصنف المادة</div>
                <div className="w-28 text-center">الوحدة</div>
                <div className="w-28 text-center">الكمية</div>
                <div className="w-32 text-center">الإفرادي (SAR)</div>
                <div className="w-40 text-center text-indigo-300">الإجمالي (SAR)</div>
                <div className="w-10"></div>
              </div>

              {formData.items.map((item, index) => (
                <div key={index} className="flex flex-col md:flex-row items-center gap-3 w-full bg-slate-950/40 hover:bg-slate-900/60 p-3 rounded-2xl border border-white/5 transition-colors group">
                  <div className="flex-1 w-full relative">
                    <span className="md:hidden text-xs text-slate-500 font-bold mb-1 block">الصنف</span>
                    <input type="text" required value={item.materialName} onChange={e => handleItemChange(index, "materialName", e.target.value)} placeholder="وصف واسم المادة..." className="w-full bg-slate-900/50 border border-white/10 hover:border-white/20 rounded-xl py-2.5 px-4 text-sm font-bold text-white focus:outline-none focus:border-indigo-500 transition-colors shadow-inner" />
                  </div>
                  <div className="w-full md:w-28 relative">
                     <span className="md:hidden text-xs text-slate-500 font-bold mb-1 block">الوحدة</span>
                     <input type="text" required list={`units-list-${index}`} value={item.unit} onChange={e => handleItemChange(index, "unit", e.target.value)} placeholder="حبه / لفة..." className="w-full bg-slate-900/50 border border-white/10 hover:border-white/20 rounded-xl py-2.5 px-4 text-sm font-bold text-white text-center focus:outline-none focus:border-indigo-500 transition-colors shadow-inner" />
                     <datalist id={`units-list-${index}`}>
                       <option value="م٢" />
                       <option value="م.ط" />
                       <option value="م٣" />
                       <option value="مقطوعية" />
                       <option value="عدد" />
                       <option value="حبة" />
                       <option value="كجم" />
                       <option value="طن" />
                       <option value="يوم" />
                       <option value="شهر" />
                       <option value="ساعة" />
                       <option value="لفة" />
                     </datalist>
                  </div>
                  <div className="w-full md:w-28 relative">
                     <span className="md:hidden text-xs text-slate-500 font-bold mb-1 block">الكمية</span>
                     <input type="number" required min="1" value={item.qty} onChange={e => handleItemChange(index, "qty", Number(e.target.value))} className="w-full bg-emerald-500/5 border border-emerald-500/20 hover:border-emerald-500/40 rounded-xl py-2.5 px-4 text-sm font-bold text-emerald-400 text-center focus:outline-none focus:border-emerald-500 transition-colors font-mono shadow-inner" />
                  </div>
                  <div className="w-full md:w-32 relative">
                     <span className="md:hidden text-xs text-slate-500 font-bold mb-1 block">السعر الإفرادي</span>
                     <input type="number" required min="0" step="any" value={item.price} onChange={e => handleItemChange(index, "price", Number(e.target.value))} className="w-full bg-amber-500/5 border border-amber-500/20 hover:border-amber-500/40 rounded-xl py-2.5 px-4 text-sm font-bold text-amber-400 text-center focus:outline-none focus:border-amber-500 transition-colors font-mono shadow-inner" />
                  </div>
                  <div className="w-full md:w-40 relative">
                    <span className="md:hidden text-xs text-slate-500 font-bold mb-1 block">الإجمالي</span>
                    <div className="w-full px-4 py-2.5 bg-indigo-500/10 rounded-xl text-center font-black text-indigo-300 font-mono text-base border border-indigo-500/20 shadow-inner">
                      {(item.qty * item.price).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </div>
                  </div>
                  <div className="w-full md:w-10 flex justify-end md:justify-center mt-2 md:mt-0">
                    {index > 0 ? (
                      <button type="button" onClick={() => handleRemoveItem(index)} className="p-2 text-slate-500 hover:text-rose-400 hover:bg-rose-500/10 rounded-xl transition-colors shrink-0">
                        <Trash2 size={20} />
                      </button>
                    ) : (
                      <div className="w-9 h-9" />
                    )}
                  </div>
                </div>
              ))}
            </div>

            <div className="mt-8 flex flex-col md:flex-row justify-between items-start md:items-center bg-gradient-to-r from-indigo-900/40 to-slate-900 p-6 rounded-2xl border border-indigo-500/20 shadow-xl relative overflow-hidden">
               <div className="absolute inset-0 bg-indigo-500/5" />
               <div className="flex flex-col gap-4 relative z-10 mb-6 md:mb-0">
                 <div className="flex items-center gap-3">
                   <div className="w-12 h-12 rounded-xl bg-indigo-500/20 flex items-center justify-center text-indigo-400 border border-indigo-500/30">
                     <Receipt size={24} />
                   </div>
                   <span className="font-bold text-xl text-slate-300">ملخص أمر الشراء (SAR)</span>
                 </div>
                 
                 {/* VAT Toggle */}
                 <div className="flex items-center gap-3 mt-2 pr-2">
                   <label className="relative inline-flex items-center cursor-pointer">
                     <input type="checkbox" className="sr-only peer" checked={formData.hasVat} onChange={e => setFormData({...formData, hasVat: e.target.checked})} />
                     <div className="w-11 h-6 bg-slate-700 peer-focus:outline-none rounded-full peer peer-checked:after:-translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:right-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-indigo-500"></div>
                   </label>
                   <span className="text-sm font-bold text-indigo-300">يخضع لضريبة القيمة المضافة (15%)</span>
                 </div>
               </div>

               <div className="relative z-10 flex flex-col items-end gap-2">
                 {formData.hasVat && (
                   <>
                     <div className="flex justify-between w-48 text-sm text-slate-400 font-medium"><span>المجموع:</span> <span className="font-mono">{calculateTotal().toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span></div>
                     <div className="flex justify-between w-48 text-sm text-rose-400 font-medium"><span>الضريبة (15%):</span> <span className="font-mono">{(calculateTotal() * 0.15).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span></div>
                     <div className="w-48 h-px bg-white/10 my-1 rounded-full"></div>
                   </>
                 )}
                 <div className="flex justify-between w-64 text-xl">
                   <span className="font-bold text-slate-300 mt-1">الإجمالي:</span>
                   <span className="font-mono text-3xl font-black text-transparent bg-clip-text bg-gradient-to-r from-indigo-300 to-indigo-500 drop-shadow-lg tracking-wider">
                     {(formData.hasVat ? calculateTotal() * 1.15 : calculateTotal()).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                   </span>
                 </div>
               </div>
            </div>
          </div>

          <div className="pt-8 flex gap-4 justify-end">
             <button type="button" onClick={() => router.back()} className="px-6 py-3 rounded-xl font-bold text-slate-400 hover:text-white hover:bg-white/5 transition-all">
               إلغاء
             </button>
            <button type="submit" disabled={isLoading} className="flex items-center gap-2 px-10 py-3 rounded-xl font-black bg-gradient-to-r from-indigo-600 to-blue-600 hover:from-indigo-500 hover:to-blue-500 text-white shadow-[0_0_20px_rgba(79,70,229,0.3)] hover:shadow-[0_0_30px_rgba(79,70,229,0.5)] transition-all hover:-translate-y-1 disabled:opacity-50 disabled:translate-y-0 text-lg">
              {isLoading ? <Loader2 size={24} className="animate-spin" /> : <Save size={24} />}
              <span>اعتماد طلب الـ PO المبدئي</span>
            </button>
          </div>
        </form>
      </motion.div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter, useParams } from "next/navigation";
import { motion } from "framer-motion";
import { 
  ShoppingCart, 
  Save, 
  ArrowRight, 
  Loader2, 
  PlusCircle,
  Trash2,
  Package,
  Building2,
  Calendar,
  User,
  Receipt
} from "lucide-react";
import axios from "axios";
import { API_BASE_URL } from "@/lib/api";

export default function EditPurchasePage() {
  const router = useRouter();
  const params = useParams();
  const orderId = params.id as string;

  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [projects, setProjects] = useState<any[]>([]);
  const [suppliers, setSuppliers] = useState<any[]>([]);

  const [formData, setFormData] = useState({
    projectId: "",
    supplierName: "",
    expectedDate: "",
    hasVat: true,
    items: [{ materialName: "", unit: "حبه", qty: 1, price: 0 }]
  });

  useEffect(() => {
    fetchData();
  }, [orderId]);

  const fetchData = async () => {
    try {
      const token = localStorage.getItem("token");
      const [pos, mats, projs, orderRes] = await Promise.all([
        axios.get(`${API_BASE_URL}/v1/integration/daftra/pms-suppliers`, { headers: { Authorization: `Bearer ${token}` } }),
        axios.get(`${API_BASE_URL}/v1/projects`, { headers: { Authorization: `Bearer ${token}` } }),
        axios.get(`${API_BASE_URL}/v1/purchases/${orderId}`, { headers: { Authorization: `Bearer ${token}` } })
      ]);

      setSuppliers(pos.data);
      setProjects(projs.data.items || projs.data);

      const ord = orderRes.data;
      if (ord.status !== 'PENDING') {
        alert("لا يمكن تعديل طلب شراء معتمد أو ملغي.");
        router.back();
        return;
      }

      setFormData({
        projectId: ord.projectId,
        supplierName: ord.supplier?.name || "",
        expectedDate: ord.expectedDate ? new Date(ord.expectedDate).toISOString().split('T')[0] : "",
        hasVat: Number(ord.taxAmount) > 0,
        items: ord.items.map((it: any) => ({
          materialName: it.material?.name || "",
          unit: it.material?.unit || "حبه",
          qty: it.quantity,
          price: it.unitPrice
        }))
      });
    } catch (err) {
      alert("تعذر جلب بيانات الطلب");
      router.back();
    } finally {
      setIsLoading(false);
    }
  };

  const calculateTotal = () => {
    return formData.items.reduce((sum, item) => sum + (item.qty * item.price), 0);
  };

  const handleAddItem = () => {
    setFormData({
      ...formData,
      items: [...formData.items, { materialName: "", unit: "حبه", qty: 1, price: 0 }]
    });
  };

  const handleRemoveItem = (index: number) => {
    const newItems = formData.items.filter((_, i) => i !== index);
    setFormData({ ...formData, items: newItems });
  };

  const handleItemChange = (index: number, field: string, value: any) => {
    const newItems = [...formData.items];
    newItems[index] = { ...newItems[index], [field]: value };
    setFormData({ ...formData, items: newItems });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      const token = localStorage.getItem("token");
      await axios.patch(
        `${API_BASE_URL}/v1/purchases/${orderId}`,
        {
          ...formData,
          expectedDate: formData.expectedDate ? new Date(formData.expectedDate).toISOString() : undefined,
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      router.push("/dashboard/purchases");
    } catch (err: any) {
      alert("حدث خطأ أثناء تحديث أمر الشراء.");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh]">
         <Loader2 className="animate-spin text-indigo-500 mb-4" size={48} />
         <p className="text-slate-400 font-bold">جاري تحميل بيانات الطلب...</p>
      </div>
    );
  }

  return (
    <div className="max-w-6xl mx-auto space-y-8 w-full animate-in fade-in zoom-in-95 duration-500 pb-12 relative">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-6">
        <div className="flex items-center gap-5">
          <button onClick={() => router.back()} className="flex items-center justify-center w-12 h-12 rounded-2xl bg-white/5 border border-white/10 hover:bg-white/10 hover:border-white/20 text-slate-300 hover:text-white transition-all shadow-lg hover:-translate-x-1">
            <ArrowRight size={22} />
          </button>
          <div>
            <h1 className="text-3xl font-black text-white tracking-tight flex items-center gap-3 drop-shadow-sm">
              <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-blue-500/20 to-indigo-500/10 flex items-center justify-center border border-blue-500/20 shadow-lg">
                <ShoppingCart className="text-blue-400" size={24} />
              </div>
              تعديل طلب الشراء
            </h1>
          </div>
        </div>
      </div>

      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="glass-dark border border-white/5 rounded-3xl p-6 sm:p-8">
        <form onSubmit={handleSubmit} className="space-y-8">

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="space-y-3">
              <label className="text-sm font-bold text-slate-300 flex items-center gap-2">
                <Building2 size={16} className="text-indigo-400" />
                المشروع المستهدف
              </label>
              <select
                required
                value={formData.projectId}
                onChange={e => setFormData({...formData, projectId: e.target.value})}
                className="w-full bg-slate-950/50 border border-white/10 rounded-xl py-3.5 px-4 text-white font-medium focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all cursor-pointer shadow-inner"
              >
                <option value="" disabled>-- اختر المشروع --</option>
                {projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
              </select>
            </div>

            <div className="space-y-3 md:col-span-2">
              <label className="text-sm font-bold text-indigo-300 flex items-center gap-2">
                <User size={16} className="text-indigo-400" />
                المورد (Supplier)
              </label>
              <input 
                type="text" 
                list="suppliersDropdown"
                required 
                value={formData.supplierName} 
                onChange={e => setFormData({...formData, supplierName: e.target.value})} 
                className="w-full bg-indigo-500/5 border border-indigo-500/20 rounded-xl py-3.5 px-4 text-white font-medium focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all shadow-inner" 
                placeholder="اسم المورد..." 
              />
              <datalist id="suppliersDropdown">
                {suppliers.map(s => <option key={s.id} value={s.name}>{s.daftraSupplierId ? '✅ مربوط بدفترة' : ''}</option>)}
              </datalist>
            </div>

            <div className="space-y-3">
              <label className="text-sm font-bold text-slate-300 flex items-center gap-2">
                <Calendar size={16} className="text-indigo-400" />
                تاريخ التوريد المتوقع
              </label>
              <input type="date" required value={formData.expectedDate} onChange={e => setFormData({...formData, expectedDate: e.target.value})} className="w-full bg-slate-950/50 border border-white/10 rounded-xl py-3.5 px-4 text-slate-200 font-medium focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all shadow-inner" style={{ colorScheme: 'dark' }} />
            </div>
          </div>

          <div className="border border-white/5 rounded-3xl overflow-hidden bg-gradient-to-b from-slate-900/50 to-slate-950/50 w-full p-6 shadow-xl relative">
            <div className="flex items-center justify-between mb-6">
              <h3 className="font-black text-xl text-white flex items-center gap-2 drop-shadow-sm">
                <Package className="text-indigo-400" size={24} />
                قائمة المواد
              </h3>
              <button type="button" onClick={handleAddItem} className="flex items-center gap-2 text-sm font-bold text-white bg-indigo-500/20 hover:bg-indigo-500/30 border border-indigo-500/30 px-4 py-2 rounded-xl transition-all shadow-lg">
                <PlusCircle size={18} /> إضافة مادة
              </button>
            </div>

            <div className="space-y-3">
              {formData.items.map((item, index) => (
                <div key={index} className="flex flex-col md:flex-row items-center gap-3 w-full bg-slate-950/40 p-3 rounded-2xl border border-white/5 transition-colors group">
                  <div className="flex-1 w-full relative">
                    <input type="text" required value={item.materialName} onChange={e => handleItemChange(index, "materialName", e.target.value)} placeholder="اسم المادة..." className="w-full bg-slate-900/50 border border-white/10 rounded-xl py-2.5 px-4 text-sm font-bold text-white focus:outline-none focus:border-indigo-500 transition-colors shadow-inner" />
                  </div>
                  <div className="w-full md:w-28 relative">
                     <input type="text" required value={item.unit} onChange={e => handleItemChange(index, "unit", e.target.value)} placeholder="الوحدة" className="w-full bg-slate-900/50 border border-white/10 rounded-xl py-2.5 px-4 text-sm font-bold text-white text-center focus:outline-none shadow-inner" />
                  </div>
                  <div className="w-full md:w-28 relative">
                     <input type="number" required min="1" value={item.qty} onChange={e => handleItemChange(index, "qty", Number(e.target.value))} className="w-full bg-emerald-500/5 border border-emerald-500/20 rounded-xl py-2.5 px-4 text-sm font-bold text-emerald-400 text-center font-mono shadow-inner" />
                  </div>
                  <div className="w-full md:w-32 relative">
                     <input type="number" required min="0" step="any" value={item.price} onChange={e => handleItemChange(index, "price", Number(e.target.value))} className="w-full bg-amber-500/5 border border-amber-500/20 rounded-xl py-2.5 px-4 text-sm font-bold text-amber-400 text-center font-mono shadow-inner" />
                  </div>
                  <div className="w-full md:w-40 relative">
                    <div className="w-full px-4 py-2.5 bg-indigo-500/10 rounded-xl text-center font-black text-indigo-300 font-mono text-base border border-indigo-500/20 shadow-inner">
                      {(item.qty * item.price).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </div>
                  </div>
                  <div className="w-full md:w-10 flex justify-end md:justify-center">
                    {formData.items.length > 1 && (
                      <button type="button" onClick={() => handleRemoveItem(index)} className="p-2 text-slate-500 hover:text-rose-400 rounded-xl transition-colors">
                        <Trash2 size={20} />
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>

            <div className="mt-8 flex flex-col md:flex-row justify-between items-start md:items-center bg-gradient-to-r from-indigo-900/40 to-slate-900 p-6 rounded-2xl border border-indigo-500/20 shadow-xl relative overflow-hidden">
               <div className="flex flex-col gap-4 relative z-10 mb-6 md:mb-0">
                 <div className="flex items-center gap-3">
                   <div className="w-12 h-12 rounded-xl bg-indigo-500/20 flex items-center justify-center text-indigo-400 border border-indigo-500/30">
                     <Receipt size={24} />
                   </div>
                   <span className="font-bold text-xl text-slate-300">ملخص أمر الشراء (SAR)</span>
                 </div>
                 <div className="flex items-center gap-3 mt-2 pr-2">
                   <label className="relative inline-flex items-center cursor-pointer">
                     <input type="checkbox" className="sr-only peer" checked={formData.hasVat} onChange={e => setFormData({...formData, hasVat: e.target.checked})} />
                     <div className="w-11 h-6 bg-slate-700 rounded-full peer peer-checked:bg-indigo-500"></div>
                   </label>
                   <span className="text-sm font-bold text-indigo-300">يخضع للضريبة (15%)</span>
                 </div>
               </div>

               <div className="relative z-10 flex flex-col items-end gap-2">
                 <div className="flex justify-between w-64 text-xl">
                   <span className="font-bold text-slate-300 mt-1">الإجمالي:</span>
                   <span className="font-mono text-3xl font-black text-transparent bg-clip-text bg-gradient-to-r from-indigo-300 to-indigo-500 drop-shadow-lg tracking-wider">
                     {(formData.hasVat ? calculateTotal() * 1.15 : calculateTotal()).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                   </span>
                 </div>
               </div>
            </div>
          </div>

          <div className="pt-8 flex gap-4 justify-end">
             <button type="button" onClick={() => router.back()} className="px-6 py-3 rounded-xl font-bold text-slate-400 hover:text-white hover:bg-white/5 transition-all">
               إلغاء
             </button>
            <button type="submit" disabled={isSubmitting} className="flex items-center gap-2 px-10 py-3 rounded-xl font-black bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white shadow-[0_0_20px_rgba(79,70,229,0.3)] transition-all hover:-translate-y-1 disabled:opacity-50 text-lg">
              {isSubmitting ? <Loader2 size={24} className="animate-spin" /> : <Save size={24} />}
              <span>تحديث البيانات</span>
            </button>
          </div>
        </form>
      </motion.div>
    </div>
  );
}

