"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { motion } from "framer-motion";
import { 
  ShoppingCart, 
  Search, 
  PlusCircle, 
  ArrowUpRight,
  Package,
  Loader2,
  Clock,
  CheckCircle2,
  Wallet,
  Activity,
  FileBox,
  TrendingUp,
  Receipt,
  Trash2,
  Edit
} from "lucide-react";
import axios from "axios";
import Link from "next/link";
import { API_BASE_URL } from "@/lib/api";

export default function PurchasesPage() {
  const router = useRouter();
  const [orders, setOrders] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [search, setSearch] = useState("");
  
  const [userPerms, setUserPerms] = useState<string[]>([]);
  const [userRole, setUserRole] = useState("");

  const fetchOrders = async () => {
    setIsLoading(true);
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get(`${API_BASE_URL}/v1/purchases`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setOrders(res.data);
    } catch (err) {}
    setIsLoading(false);
  };

  useEffect(() => {
    const userStr = localStorage.getItem("user");
    if (userStr) {
      try {
        const u = JSON.parse(userStr);
        setUserPerms(u.permissions || []);
        setUserRole(u.role || "");
      } catch (e) {}
    }
    fetchOrders();
  }, []);

  const hasPermission = (perm: string) => {
    if (userRole === "Admin" || userRole === "System Admin") return true;
    return userPerms.includes(perm);
  };

  const statusMap: Record<string, { label: string, color: string, icon: any }> = {
    PENDING: { label: "قيد المراجعة", color: "text-amber-500 bg-amber-500/10 border-amber-500/20", icon: Clock },
    APPROVED: { label: "معتمد (Approved)", color: "text-blue-500 bg-blue-500/10 border-blue-500/20 shadow-[0_0_10px_rgba(59,130,246,0.2)]", icon: CheckCircle2 },
    DELIVERED: { label: "تم استلام الموقع", color: "text-emerald-500 bg-emerald-500/10 border-emerald-500/20 shadow-[0_0_10px_rgba(16,185,129,0.2)]", icon: Package },
  };

  const totalSpend = orders.filter(o => o.status !== 'REJECTED').reduce((sum, o) => sum + (Number(o.totalAmount) || 0), 0);
  const pendingCount = orders.filter(o => o.status === 'PENDING').length;
  const approvedCount = orders.filter(o => o.status === 'APPROVED' || o.status === 'DELIVERED').length;

  return (
    <div className="space-y-6 w-full animate-in fade-in zoom-in-95 duration-500">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-white mb-2 flex items-center gap-3">
            <ShoppingCart className="text-indigo-400" size={28} />
            إدارة المشتريات والمواد (PO)
          </h1>
          <p className="text-slate-400 text-sm">تتبع طلبات الاستعاضة للمواد وربط التكاليف ببند التنفيذ الذاتي.</p>
        </div>
        
        <div className="flex items-center gap-3">
          {hasPermission('PO_CREATE') && (
            <Link href="/dashboard/purchases/create" className="relative flex items-center gap-2 font-black py-3 px-6 rounded-xl transition-all shadow-[0_0_20px_rgba(79,70,229,0.4)] hover:shadow-[0_0_30px_rgba(79,70,229,0.6)] group bg-gradient-to-r from-indigo-600 to-blue-600 hover:from-indigo-500 hover:to-blue-500 text-white overflow-hidden hover:-translate-y-1">
              <div className="absolute inset-0 bg-white/20 translate-y-full group-hover:translate-y-0 transition-transform duration-300" />
              <PlusCircle size={20} className="group-hover:rotate-90 transition-transform relative z-10" />
              <span className="relative z-10 text-sm">إنشاء طلب شراء (PO)</span>
            </Link>
          )}
        </div>
      </div>

      {/* Top Value Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-indigo-900/40 to-slate-900 border border-indigo-500/20 p-6 flex items-center justify-between group shadow-xl">
           <div className="absolute inset-0 bg-indigo-500/10 opacity-0 group-hover:opacity-100 transition-opacity" />
           <div>
             <p className="text-indigo-400 font-bold mb-1 flex items-center gap-2">
               <Wallet size={16} /> إجمالي المشتريات المعتمدة
             </p>
             <h2 className="text-3xl font-black text-white font-mono">{totalSpend.toLocaleString('en-US', { minimumFractionDigits: 2 })} <span className="text-sm text-slate-500">SAR</span></h2>
           </div>
           <div className="w-14 h-14 rounded-2xl bg-indigo-500/20 flex items-center justify-center text-indigo-400 border border-indigo-500/30 shadow-inner group-hover:scale-110 transition-transform">
             <Receipt size={28} />
           </div>
        </div>

        <div className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-amber-900/40 to-slate-900 border border-amber-500/20 p-6 flex items-center justify-between group shadow-xl">
           <div className="absolute inset-0 bg-amber-500/10 opacity-0 group-hover:opacity-100 transition-opacity" />
           <div>
             <p className="text-amber-400 font-bold mb-1 flex items-center gap-2">
               <Clock size={16} /> طلبات قيد المراجعة
             </p>
             <h2 className="text-3xl font-black text-white font-mono">{pendingCount} <span className="text-sm text-slate-500">طلبات شراء</span></h2>
           </div>
           <div className="w-14 h-14 rounded-2xl bg-amber-500/20 flex items-center justify-center text-amber-400 border border-amber-500/30 shadow-inner group-hover:scale-110 transition-transform">
             <Activity size={28} />
           </div>
        </div>

        <div className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-emerald-900/40 to-slate-900 border border-emerald-500/20 p-6 flex items-center justify-between group shadow-xl">
           <div className="absolute inset-0 bg-emerald-500/10 opacity-0 group-hover:opacity-100 transition-opacity" />
           <div>
             <p className="text-emerald-400 font-bold mb-1 flex items-center gap-2">
               <CheckCircle2 size={16} /> طلبات مكتملة وموردة
             </p>
             <h2 className="text-3xl font-black text-white font-mono">{approvedCount} <span className="text-sm text-slate-500">طلبات شراء</span></h2>
           </div>
           <div className="w-14 h-14 rounded-2xl bg-emerald-500/20 flex items-center justify-center text-emerald-400 border border-emerald-500/30 shadow-inner group-hover:scale-110 transition-transform">
             <FileBox size={28} />
           </div>
        </div>
      </div>

      <div className="bg-slate-900/60 backdrop-blur-md border border-white/10 p-3 rounded-2xl flex items-center gap-4 shadow-lg">
        <div className="relative flex-1 group">
          <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-500 transition-colors" size={18} />
          <input
            type="text"
            placeholder="بحث برقم الطلب (PO)..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full bg-slate-900/50 border border-slate-800 rounded-xl py-2.5 pr-12 pl-4 text-white text-sm placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all"
          />
        </div>
      </div>

      <div className="rounded-3xl glass border border-white/5 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right text-sm">
            <thead className="bg-slate-900/50 text-slate-400 border-b border-white/5 uppercase font-medium">
              <tr>
                <th className="px-6 py-4">رقم الـ PO</th>
                <th className="px-6 py-4">المشروع</th>
                <th className="px-6 py-4">المورد / المورد المحتمل</th>
                <th className="px-6 py-4 text-indigo-400">الإجمالي (SAR)</th>
                <th className="px-6 py-4">تاريخ الطلب</th>
                <th className="px-6 py-4 text-center">حالة الطلب</th>
                <th className="px-6 py-4 text-center">الإجراءات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/5 text-slate-300">
              {isLoading ? (
                <tr>
                   <td colSpan={7} className="px-6 py-12 text-center text-slate-400"><Loader2 className="animate-spin mx-auto text-indigo-500" size={24} /></td>
                </tr>
              ) : orders.length === 0 ? (
                <tr>
                   <td colSpan={7} className="px-6 py-12 text-center text-slate-400 glass">لا توجد طلبات شراء مسجلة بعد.</td>
                </tr>
              ) : (
                orders.filter(o => o.poNumber.includes(search)).map((ord, i) => (
                  <motion.tr 
                    initial={{ opacity: 0, scale: 0.98 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{ delay: i * 0.05 }}
                    key={ord.id} 
                    onClick={() => router.push(`/dashboard/purchases/${ord.id}`)}
                    className="hover:bg-indigo-500/[0.03] transition-colors cursor-pointer group border-b border-white/5 active:bg-indigo-500/10"
                  >
                    <td className="px-6 py-5 font-mono font-bold text-white"><span className="text-indigo-400">#</span>{ord.poNumber}</td>
                    <td className="px-6 py-5 font-bold text-white">{ord.project?.name || "عام (بدون مشروع)"}</td>
                    <td className="px-6 py-5">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-full bg-slate-800 flex items-center justify-center text-slate-400 border border-slate-700 font-bold text-xs shadow-inner">
                           {ord.supplier?.name?.charAt(0) || '?'}
                        </div> 
                        <span className="font-semibold text-slate-300">{ord.supplier?.name || "مورد غير محدد"}</span>
                      </div>
                    </td>
                    <td className="px-6 py-5 font-mono font-black text-transparent bg-clip-text bg-gradient-to-r from-indigo-300 to-indigo-500 text-lg border-x border-white/5 bg-slate-900/40">
                      {Number(ord.totalAmount).toLocaleString('en-US', { minimumFractionDigits: 2 })}
                    </td>
                    <td className="px-6 py-5 text-slate-400 font-medium font-mono text-xs">{new Date(ord.issueDate).toLocaleDateString('en-US', { day: '2-digit', month: 'short', year:'numeric' })}</td>
                    <td className="px-6 py-5">
                      <div className="flex justify-center">
                        <div className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold border ${statusMap[ord.status]?.color || statusMap['PENDING'].color}`}>
                          {(() => {
                            const IconComp = statusMap[ord.status]?.icon || Clock;
                            return <IconComp size={14} />;
                          })()}
                          {statusMap[ord.status]?.label || ord.status}
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-5 text-center">
                      {ord.status === 'PENDING' ? (
                        <div className="flex items-center justify-center gap-2">
                          {hasPermission('PO_APPROVE') && (
                            <button 
                              onClick={async (e) => {
                                e.stopPropagation();
                                if(!confirm("هل أنت متأكد من اعتماد طلب الشراء؟ (سيتم ترحيله إلى دفترة)")) return;
                                try {
                                  await axios.patch(`${API_BASE_URL}/v1/purchases/${ord.id}/approve`, {}, {
                                    headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
                                  });
                                  fetchOrders();
                                } catch(err: any) {
                                  const errData = err.response?.data || err.message;
                                  alert(typeof errData === 'object' ? JSON.stringify(errData, null, 2) : errData);
                                }
                              }}
                              title="اعتماد وترحيل الشراء"
                              className="p-2.5 bg-emerald-500/10 text-emerald-500 hover:bg-emerald-500 hover:text-white rounded-xl transition-all shadow-sm"
                            >
                              <CheckCircle2 size={18} />
                            </button>
                          )}

                          {hasPermission('PO_CREATE') && (
                            <>
                              <button 
                                onClick={(e) => {
                                  e.stopPropagation();
                                  alert('شاشة التعديل قيد التطوير وستتوفر قريباً!');
                                }}
                                title="تعديل طلب الشراء"
                                className="p-2.5 bg-blue-500/10 text-blue-500 hover:bg-blue-500 hover:text-white rounded-xl transition-all shadow-sm"
                              >
                                <Edit size={18} />
                              </button>
                              
                              <button
                                onClick={async (e) => {
                                  e.stopPropagation();
                                  if(!confirm("هل أنت متأكد من حذف وإلغاء طلب الشراء بشكل نهائي؟")) return;
                                  try {
                                    await axios.delete(`${API_BASE_URL}/v1/purchases/${ord.id}`, {
                                      headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
                                    });
                                    fetchOrders();
                                  } catch(err: any) {
                                    alert("فشل الحذف. قد يكون الطلب معتمداً مسبقاً.");
                                  }
                                }}
                                title="إلغاء وحذف الطلب"
                                className="p-2.5 bg-rose-500/10 text-rose-500 hover:bg-rose-500 hover:text-white rounded-xl transition-all shadow-sm"
                              >
                                <Trash2 size={18} />
                              </button>
                            </>
                          )}
                        </div>
                      ) : (
                        <div className="flex justify-center">
                           <span className="text-slate-500 text-xs font-bold bg-slate-900 px-3 py-1.5 rounded-lg border border-slate-800 shadow-inner opacity-50">مكتمل ✅</span>
                        </div>
                      )}
                    </td>
                  </motion.tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter, useParams } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import { 
  FilePlus, 
  Save, 
  ArrowRight, 
  Loader2, 
  Plus,
  Trash2,
  ListOrdered,
  Printer,
  Building2,
  FileSignature,
  FileText,
  ScrollText,
  Wand2,
  CheckCircle2,
  FileSpreadsheet,
  LayoutTemplate,
  Link2Off
} from "lucide-react";
import axios from "axios";
import { API_BASE_URL } from "@/lib/api";
import { exportToCsv } from "@/lib/exportUtils";
import { useDownloadPdf } from "@/hooks/useDownloadPdf";
import PrintHeader from "../../components/PrintHeader";
import PrintFooter from "../../components/PrintFooter";
import PrintLetterhead from "../../components/PrintLetterhead";

export default function EditQuotationPage() {
  const router = useRouter();
  const params = useParams();
  const quotationId = params.id as string;

  const [isLoading, setIsLoading] = useState(false);
  const [isFetching, setIsFetching] = useState(true);
  const [printMeta, setPrintMeta] = useState({ date: "", ref: "" });

  const [userPerms, setUserPerms] = useState<string[]>([]);
  const [userRole, setUserRole] = useState("");

  const [formData, setFormData] = useState({
    title: "",
    clientName: "",
    hasVat: false,
    technicalOffer: "",
    termsConditions: "",
    status: "DRAFT",
    projectId: null as string | null,
    createdBy: "",
    approvedBy: "",
    approvedAt: "",
    createdAt: "",
    updatedAt: "",
    items: [{ itemCode: "01", description: "", unit: "م٢", quantity: 1, unitPrice: 0 }]
  });

  const [templates, setTemplates] = useState<any[]>([]);
  const [showTemplates, setShowTemplates] = useState(false);
  const { pdfRef, downloadPdf } = useDownloadPdf();

  useEffect(() => {
    const userStr = localStorage.getItem("user");
    if (userStr) {
      try {
        const u = JSON.parse(userStr);
        setUserPerms(u.permissions || []);
        setUserRole(u.role || "");
      } catch (e) {}
    }

    if (quotationId) {
      fetchQuotation();
    }
    fetchTemplates();
  }, [quotationId]);

  const fetchTemplates = async () => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get(`${API_BASE_URL}/v1/quotation-templates`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setTemplates(res.data || []);
    } catch {}
  };

  const hasPermission = (perm: string) => {
    if (userRole === "Admin" || userRole === "System Admin") return true;
    return userPerms.includes(perm);
  };

  const fetchQuotation = async () => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get(`${API_BASE_URL}/v1/quotations/${quotationId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });

      const q = res.data;
      setFormData({
        title: q.title || "",
        clientName: q.client?.name || "",
        hasVat: q.hasVat || false,
        technicalOffer: q.technicalOffer || "",
        termsConditions: q.termsConditions || "",
        status: q.status || "DRAFT",
        projectId: q.projectId || null,
        createdBy: q.createdBy || "",
        approvedBy: q.approvedBy || "",
        approvedAt: q.approvedAt || "",
        createdAt: q.createdAt || "",
        updatedAt: q.updatedAt || "",
        items: q.items?.length > 0 ? q.items.map((i: any) => ({
          itemCode: i.itemCode,
          description: i.description,
          unit: i.unit,
          quantity: i.quantity,
          unitPrice: i.unitPrice
        })) : [{ itemCode: "01", description: "", unit: "م٢", quantity: 1, unitPrice: 0 }]
      });

      setPrintMeta({
        date: new Date(q.createdAt || new Date()).toLocaleDateString('ar-SA', { year: 'numeric', month: 'long', day: 'numeric' }),
        ref: q.quotationNumber
      });
    } catch (err) {
      console.error(err);
      alert("تعذر جلب بيانات عرض السعر.");
      router.push("/dashboard/quotations");
    } finally {
      setIsFetching(false);
    }
  };

  const calculateSubTotal = () => {
    return formData.items.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  };

  const calculateVat = () => {
    return formData.hasVat ? calculateSubTotal() * 0.15 : 0;
  };

  const calculateTotal = () => {
    return calculateSubTotal() + calculateVat();
  };

  const handleAddItem = () => {
    const nextCode = (formData.items.length + 1).toString().padStart(2, '0');
    setFormData({
      ...formData,
      items: [...formData.items, { itemCode: nextCode, description: "", unit: "م٢", quantity: 1, unitPrice: 0 }]
    });
  };

  const handleRemoveItem = (index: number) => {
    const newItems = formData.items.filter((_, i) => i !== index);
    const reindexedItems = newItems.map((item, i) => ({
      ...item,
      itemCode: (i + 1).toString().padStart(2, '0')
    }));
    setFormData({ ...formData, items: reindexedItems });
  };

  const handleItemChange = (index: number, field: string, value: any) => {
    const newItems = [...formData.items];
    newItems[index] = { ...newItems[index], [field]: value };
    setFormData({ ...formData, items: newItems });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const token = localStorage.getItem("token");
      await axios.patch(
        `${API_BASE_URL}/v1/quotations/${quotationId}`,
        formData,
        { headers: { Authorization: `Bearer ${token}` } }
      );
      alert("تم تحديث عرض السعر بنجاح!");
    } catch (err: any) {
      alert("حدث خطأ أثناء الرفع والتعديل.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleConvertToProject = async () => {
    if (!confirm("هل أنت متأكد من تحويل عرض السعر لاعتماد وإنشاء مشروع تنفيذي؟")) return;
    setIsLoading(true);
    try {
      const token = localStorage.getItem("token");
      await axios.post(`${API_BASE_URL}/v1/quotations/${quotationId}/convert`, {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      alert("🎉 تم إنشاء المشروع بنجاح من عرض السعر!");
      fetchQuotation();
    } catch (err) {
      alert("فشل تحويل عرض السعر لمشروع.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleUnlink = async () => {
    if (!confirm("هل أنت متأكد من فك ارتباط عرض السعر بالمشروع يدوياً؟ سيتحول العرض لمسودة.")) return;
    setIsLoading(true);
    try {
      const token = localStorage.getItem("token");
      await axios.post(`${API_BASE_URL}/v1/quotations/${quotationId}/unlink`, {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      alert("تم فك الارتباط بنجاح. يمكنك الآن تعديل العرض أو حذفه.");
      fetchQuotation();
    } catch (err: any) {
      alert("فشل فك الارتباط. تأكد من تحديث النظام.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleDeleteQuotation = async () => {
    if (!confirm("هل أنت متأكد من حذف عرض السعر بشكل نهائي؟ هذا الإجراء لا يمكن التراجع عنه.")) return;
    setIsLoading(true);
    try {
      const token = localStorage.getItem("token");
      await axios.delete(`${API_BASE_URL}/v1/quotations/${quotationId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      alert("تم حذف عرض السعر بنجاح.");
      router.push("/dashboard/quotations");
    } catch (err: any) {
      alert(err.response?.data?.message || "فشل حذف عرض السعر.");
    } finally {
      setIsLoading(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const handleExportExcel = () => {
    if (!formData.items || formData.items.length === 0) return;
    const exportData = formData.items.map((item: any) => ({
      "م": item.itemCode,
      "وصف البند": item.description,
      "الوحدة": item.unit,
      "الكمية": item.quantity,
      "سعر الوحدة": item.unitPrice,
      "الإجمالي": item.quantity * item.unitPrice
    }));
    exportToCsv(`Quotation_${printMeta.ref || 'Draft'}.csv`, exportData);
  };

  if (isFetching) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] print:hidden">
         <Loader2 className="animate-spin text-pink-500 mb-4" size={48} />
         <p className="text-slate-400 font-bold tracking-widest text-sm">جاري جلب عرض السعر...</p>
      </div>
    );
  }

  const isEditable = formData.status !== 'APPROVED' || hasPermission('QUOTATION_FORCE_EDIT');

  return (
    <>
      <div className="max-w-[1600px] mx-auto space-y-8 w-full animate-in fade-in zoom-in-95 duration-500 pb-12 print:hidden relative">
        <div className="absolute top-0 right-1/4 w-[500px] h-[500px] bg-indigo-600/10 rounded-full blur-[150px] pointer-events-none -z-10" />

        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-6">
          <div className="flex items-center gap-5">
            <button onClick={() => router.back()} className="flex items-center justify-center w-12 h-12 rounded-2xl bg-white/5 border border-white/10 hover:bg-white/10 hover:border-white/20 text-slate-300 hover:text-white transition-all shadow-lg hover:-translate-x-1">
              <ArrowRight size={22} />
            </button>
            <div>
              <h1 className="text-3xl font-black text-white tracking-tight flex items-center gap-3 drop-shadow-sm">
                <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-indigo-500/20 to-blue-500/10 flex items-center justify-center border border-indigo-500/20 shadow-lg">
                  <FileText className="text-indigo-400" size={24} />
                </div>
                مراجعة وتعديل عرض السعر
              </h1>
              <p className="text-slate-400 text-sm mt-2 font-medium flex items-center gap-2 font-mono">
                {printMeta.ref} - {formData.clientName}
                {formData.projectId && (
                  <span className="bg-emerald-500/10 text-emerald-400 px-2.5 py-0.5 rounded-full text-xs font-bold border border-emerald-500/20 flex items-center gap-1">
                    <CheckCircle2 size={14} /> تم تحويله لمشروع
                  </span>
                )}
              </p>
            </div>
          </div>

          <div className="flex flex-col items-end gap-3 w-full sm:w-auto">
            <div className="flex items-center gap-3 bg-slate-900/50 p-1.5 rounded-xl border border-white/5">
              <span className="text-sm font-bold text-slate-400 mr-2">حالة العرض:</span>
              <select 
                value={formData.status} 
                onChange={e => setFormData({...formData, status: e.target.value})}
                disabled={!!formData.projectId || !hasPermission('QUOTATION_APPROVE')}
                className={`bg-slate-950 border rounded-lg px-3 py-1.5 text-sm font-bold outline-none transition-colors appearance-none ${hasPermission('QUOTATION_APPROVE') ? 'cursor-pointer' : 'cursor-not-allowed opacity-70'} ${
                  formData.status === 'APPROVED' ? 'text-emerald-400 border-emerald-500/30' : 
                  formData.status === 'REJECTED' ? 'text-rose-400 border-rose-500/30' : 
                  formData.status === 'SUBMITTED' ? 'text-blue-400 border-blue-500/30' : 
                  'text-slate-300 border-slate-700'
                }`}
              >
                <option value="DRAFT">مسودة (Draft)</option>
                <option value="SUBMITTED">مُرسل للعميل (Submitted)</option>
                <option value="APPROVED">معتمد (Approved)</option>
                <option value="REJECTED">مرفوض (Rejected)</option>
              </select>
            </div>

            <div className="flex items-center gap-3 w-full sm:w-auto">
              {formData.status === 'APPROVED' && !formData.projectId && hasPermission('QUOTATION_APPROVE') && (
                <button type="button" onClick={handleConvertToProject} className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-6 py-3 rounded-xl font-black bg-gradient-to-r from-amber-500 to-orange-600 hover:from-amber-400 hover:to-orange-500 text-white shadow-[0_0_20px_rgba(245,158,11,0.3)] hover:shadow-[0_0_30px_rgba(245,158,11,0.5)] transition-all animate-pulse text-sm">
                  <Wand2 size={18} /> تحويل لمشروع تنفيذي
                </button>
              )}
              <button type="button" onClick={handleExportExcel} className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-6 py-3 rounded-xl border border-emerald-500/30 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-400 font-bold transition-all shadow-lg text-sm">
                <FileSpreadsheet size={18} /> Excel
              </button>
              <button type="button" onClick={() => downloadPdf(`Quotation_${printMeta.ref || 'draft'}.pdf`)} className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-6 py-3 rounded-xl border border-rose-500/30 bg-rose-500/10 hover:bg-rose-500/20 text-rose-400 font-bold transition-all shadow-lg text-sm">
                <Printer size={18} /> PDF
              </button>
              <button type="button" onClick={handlePrint} className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-6 py-3 rounded-xl border border-indigo-500/30 bg-indigo-500/10 hover:bg-indigo-500/20 text-indigo-400 font-bold transition-all shadow-lg text-sm">
                <Printer size={18} /> معاينة وطباعة
              </button>
              {isEditable && hasPermission('QUOTATION_CREATE') && (
                <button onClick={handleSubmit} disabled={isLoading} className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-8 py-3 rounded-xl font-bold bg-gradient-to-r from-indigo-600 to-blue-600 hover:from-indigo-500 hover:to-blue-500 text-white shadow-[0_0_20px_rgba(79,70,229,0.3)] hover:shadow-[0_0_30px_rgba(79,70,229,0.5)] transition-all hover:-translate-y-1 text-sm disabled:opacity-50">
                  {isLoading ? <Loader2 size={18} className="animate-spin" /> : <Save size={18} />} تحديث البيانات
                </button>
              )}
              {formData.status === 'APPROVED' && hasPermission('QUOTATION_FORCE_DELETE') && (
                <div className="flex gap-2 w-full sm:w-auto">
                  {formData.projectId && (
                    <button type="button" onClick={handleUnlink} disabled={isLoading} className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-4 py-3 rounded-xl border border-amber-500/30 bg-amber-500/10 hover:bg-amber-500/20 text-amber-400 font-bold transition-all shadow-lg text-sm" title="فك الارتباط يدوياً">
                      <Link2Off size={18} /> فك الارتباط
                    </button>
                  )}
                  <button type="button" onClick={handleDeleteQuotation} disabled={isLoading} className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-6 py-3 rounded-xl border border-rose-500/30 bg-rose-500/10 hover:bg-rose-500/20 text-rose-400 font-bold transition-all shadow-lg text-sm">
                    <Trash2 size={18} /> حذف العرض
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>

        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="glass-dark border border-white/5 rounded-3xl p-8 relative overflow-hidden shadow-2xl">
          <div className="absolute top-0 inset-x-0 h-1 bg-gradient-to-r from-indigo-500 via-blue-500 to-teal-400 opacity-50" />

          <form className="space-y-10">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 bg-slate-900/40 p-6 rounded-2xl border border-white/5 shadow-inner">
              <div className="space-y-3">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                  <Building2 size={14} className="text-indigo-400" />
                  العميل / الجهة المالكة المستهدفة
                </label>
                <input 
                  type="text" 
                  required 
                  disabled={!isEditable}
                  value={formData.clientName} 
                  onChange={e => setFormData({...formData, clientName: e.target.value})} 
                  className={`w-full bg-slate-950/50 border border-slate-700/80 rounded-xl py-3.5 px-4 text-white text-base placeholder-slate-600 focus:outline-none focus:border-indigo-500/50 focus:ring-1 focus:ring-indigo-500/50 transition-all shadow-inner ${!isEditable ? 'opacity-60 cursor-not-allowed' : ''}`} 
                />
              </div>

              <div className="space-y-3">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                  <FileSignature size={14} className="text-indigo-400" />
                  وصف المشروع أو عنوان عرض السعر
                </label>
                <input 
                  type="text" 
                  required 
                  disabled={!isEditable}
                  value={formData.title} 
                  onChange={e => setFormData({...formData, title: e.target.value})} 
                  className={`w-full bg-slate-950/50 border border-slate-700/80 rounded-xl py-3.5 px-4 text-white text-base placeholder-slate-600 focus:outline-none focus:border-indigo-500/50 focus:ring-1 focus:ring-indigo-500/50 transition-all shadow-inner ${!isEditable ? 'opacity-60 cursor-not-allowed' : ''}`} 
                />
              </div>

              <div className="md:col-span-2 space-y-3 pt-2">
                <label className="flex items-center gap-3 bg-slate-950/80 border border-slate-800 p-4 rounded-xl cursor-pointer hover:border-indigo-500/30 transition-colors w-max">
                  <input 
                    type="checkbox" 
                    disabled={!isEditable}
                    checked={formData.hasVat} 
                    onChange={e => setFormData({...formData, hasVat: e.target.checked})}
                    className={`w-5 h-5 rounded accent-indigo-500 border-slate-700 ${!isEditable ? 'opacity-60 cursor-not-allowed' : ''}`} 
                  />
                  <span className={`font-bold text-sm ${!isEditable ? 'text-slate-400' : 'text-white'}`}>تطبيق ضريبة القيمة المضافة 15% 🇸🇦</span>
                </label>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 bg-slate-900/40 p-6 rounded-2xl border border-white/5 shadow-inner relative">
               {/* Template Selector Float */}
               <div className="md:col-span-2 flex justify-end mb-2">
                 <div className="relative">
                    <button 
                      type="button"
                      disabled={!isEditable}
                      onClick={() => setShowTemplates(!showTemplates)}
                      className={`flex items-center gap-2 px-4 py-2 bg-indigo-500/10 hover:bg-indigo-500/20 border border-indigo-500/30 rounded-xl text-indigo-400 text-xs font-bold transition-all shadow-lg ${!isEditable ? 'opacity-50 cursor-not-allowed' : ''}`}
                    >
                      <LayoutTemplate size={14} />
                      {showTemplates ? 'إغلاق القوالب' : 'إدراج من قالب جاهز'}
                    </button>

                    <AnimatePresence>
                      {showTemplates && (
                        <motion.div 
                          initial={{ opacity: 0, y: 10, scale: 0.95 }}
                          animate={{ opacity: 1, y: 0, scale: 1 }}
                          exit={{ opacity: 0, y: 10, scale: 0.95 }}
                          className="absolute left-0 top-full mt-2 w-72 bg-slate-900 border border-white/10 rounded-2xl shadow-2xl z-50 p-2 overflow-hidden"
                        >
                           <div className="p-3 border-b border-white/5 mb-1">
                              <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">اختر قالباً للتعبئة التلقائية</h4>
                           </div>
                           <div className="max-h-64 overflow-y-auto custom-scrollbar">
                              {templates.length === 0 ? (
                                <p className="p-4 text-xs text-slate-600 text-center italic">لا توجد قوالب مضافة بعد</p>
                              ) : (
                                templates.map(t => (
