// Donut chart showing Cost distribution
const ExpensesDonutChart = ({ data }: { data: any[] }) => {
  if (!data || data.length === 0) {
    return <div className="text-slate-500 text-xs text-center py-12">لا توجد نفقات للتحليل</div>;
  }

  const radius = 50;
