                  className="w-full bg-slate-900/60 border border-white/10 rounded-xl py-3 px-4 text-emerald-400 font-mono text-sm tracking-widest focus:outline-none focus:border-emerald-500/50"
                  dir="ltr"
                  autoComplete="new-password"
